-- ── helpers ─────────────────────────────────────────────────────────────

-- Days are Vietnamese days: a learning day ends at midnight in Hà Nội.
create or replace function public.cortex_today()
returns date language sql stable as $$
  select (now() at time zone 'Asia/Ho_Chi_Minh')::date;
$$;

create or replace function public.classroom_code()
returns text language plpgsql volatile set search_path = public as $$
declare
  alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  c text;
begin
  loop
    c := '';
    for i in 1..6 loop
      c := c || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from cortex_classes where code = c);
  end loop;
  return c;
end;
$$;

create or replace function public.classroom_is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from cortex_staff where user_id = auth.uid() and role = 'admin');
$$;

create or replace function public.classroom_is_org_admin(p_org uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select classroom_is_admin() or exists (
    select 1 from cortex_org_members where org_id = p_org and user_id = auth.uid() and role = 'admin'
  );
$$;

-- The teacher of a class, an admin of its center, or a system admin (support).
create or replace function public.classroom_can_teach(p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from cortex_classes c
    where c.id = p_class and (
      c.teacher_id = auth.uid()
      or exists (select 1 from cortex_org_members m where m.org_id = c.org_id and m.user_id = auth.uid() and m.role = 'admin')
      or exists (select 1 from cortex_staff s where s.user_id = auth.uid() and s.role = 'admin')
    )
  );
$$;

-- A module hook (docs/CLASSROOM.md, "SQL hooks"): classroom_<app>_<hook>, called only
-- for registered apps, so an app id can never name another function.
create or replace function public.classroom_hook_name(p_app text, p_hook text)
returns text language plpgsql stable set search_path = public as $$
begin
  if p_app is null or p_app !~ '^[a-z][a-z0-9_]{1,20}$' or not exists (select 1 from cortex_apps where id = p_app) then
    raise exception 'unknown app';
  end if;
  if to_regprocedure(format('public.classroom_%s_%s', p_app, p_hook) ||
      case p_hook
        when 'clean_payload' then '(text, jsonb)'
        when 'clean_metrics' then '(uuid, jsonb)'
        when 'rank' then '(jsonb)'
        when 'after_assign' then '(uuid, uuid, jsonb)'
        when 'clean_settings' then '(jsonb)'
      end) is null then
    return null;
  end if;
  return format('classroom_%s_%s', p_app, p_hook);
end;
$$;

-- Apps a class may use: registered, no duplicates.
create or replace function public.classroom_clean_apps(p_apps text[])
returns text[] language sql stable set search_path = public as $$
  select coalesce(array_agg(distinct a order by a), '{}') from unnest(coalesce(p_apps, '{}')) a
  where exists (select 1 from cortex_apps where id = a);
$$;

-- Each app's settings, cleaned by its module (unknown keys dropped).
create or replace function public.classroom_clean_settings(p_apps text[], p_settings jsonb)
returns jsonb language plpgsql stable set search_path = public as $$
declare
  a text;
  hook text;
  out jsonb := '{}';
  s jsonb;
begin
  foreach a in array p_apps loop
    s := coalesce(p_settings -> a, '{}'::jsonb);
    hook := classroom_hook_name(a, 'clean_settings');
    if hook is not null then execute format('select %I($1)', hook) into s using s; else s := '{}'::jsonb; end if;
    out := out || jsonb_build_object(a, s);
  end loop;
  return out;
end;
$$;

-- ── who is who ──────────────────────────────────────────────────────────

-- What the teacher app may show this person; empty roles = only the "contact us" page.
create or replace function public.classroom_whoami()
returns jsonb language sql stable security definer set search_path = public, auth as $$
  select jsonb_build_object(
    'email', (select email from auth.users where id = auth.uid()),
    'admin', exists (select 1 from cortex_staff where user_id = auth.uid() and role = 'admin'),
    'indie', exists (select 1 from cortex_staff where user_id = auth.uid() and role in ('indie','admin')),
    'orgs', coalesce((
      select jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name, 'role', m.role, 'seats', o.seats) order by o.name)
      from cortex_org_members m join cortex_orgs o on o.id = m.org_id where m.user_id = auth.uid()
    ), '[]'::jsonb),
    'apps', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name) order by created_at) from cortex_apps), '[]'::jsonb)
  );
$$;

-- ── centers (system admin) ──────────────────────────────────────────────

create or replace function public.classroom_org_create(p_name text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  oid uuid;
begin
  if not classroom_is_admin() then raise exception 'not an admin'; end if;
  insert into cortex_orgs (name, owner_id) values (trim(p_name), auth.uid()) returning id into oid;
  return jsonb_build_object('id', oid);
end;
$$;

create or replace function public.classroom_org_update(p_org uuid, p_name text default null, p_seats int default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if p_seats is not null and not classroom_is_admin() then raise exception 'not an admin'; end if;
  if p_name is not null and not classroom_is_org_admin(p_org) then raise exception 'not an admin'; end if;
  update cortex_orgs set name = coalesce(nullif(trim(p_name), ''), name), seats = coalesce(p_seats, seats) where id = p_org;
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.classroom_admin_overview()
returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
begin
  if not classroom_is_admin() then raise exception 'not an admin'; end if;
  return jsonb_build_object(
    'orgs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', o.name, 'seats', o.seats, 'created_at', o.created_at,
        'used', (select count(distinct m.user_id) from cortex_class_members m join cortex_classes c on c.id = m.class_id where c.org_id = o.id and not c.archived),
        'admins', (select count(*) from cortex_org_members where org_id = o.id and role = 'admin'),
        'teachers', (select count(*) from cortex_org_members where org_id = o.id),
        'classes', (select count(*) from cortex_classes where org_id = o.id and not archived)
      ) order by o.created_at desc)
      from cortex_orgs o
    ), '[]'::jsonb),
    'indie', coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id', s.user_id, 'email', u.email, 'since', s.created_at,
        'classes', (select count(*) from cortex_classes c where c.teacher_id = s.user_id and c.org_id is null and not c.archived)
      ) order by s.created_at desc)
      from cortex_staff s join auth.users u on u.id = s.user_id where s.role = 'indie'
    ), '[]'::jsonb)
  );
end;
$$;

create or replace function public.classroom_indie_revoke(p_user uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not classroom_is_admin() then raise exception 'not an admin'; end if;
  delete from cortex_staff where user_id = p_user and role = 'indie';
  return jsonb_build_object('ok', true);
end;
$$;

-- ── invitations ─────────────────────────────────────────────────────────

-- org_admin and indie: system admin only; org_teacher: an admin of that center.
create or replace function public.classroom_invite_create(p_kind text, p_org uuid default null, p_note text default null, p_days int default 7)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  -- Two random UUIDs: 244 random bits, no extension needed.
  t text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_kind = 'indie' then
    if not classroom_is_admin() then raise exception 'not an admin'; end if;
    p_org := null;
  elsif p_kind = 'org_admin' then
    if not classroom_is_admin() or p_org is null then raise exception 'not an admin'; end if;
  elsif p_kind = 'org_teacher' then
    if p_org is null or not classroom_is_org_admin(p_org) then raise exception 'not an admin'; end if;
  else
    raise exception 'bad invite';
  end if;
  insert into cortex_invites (token, kind, org_id, note, created_by, expires_at)
  values (t, p_kind, p_org, nullif(trim(p_note), ''), auth.uid(), now() + make_interval(days => least(greatest(coalesce(p_days, 7), 1), 30)));
  return jsonb_build_object('token', t);
end;
$$;

-- What an invitation is for, shown before signing in. Says nothing about who sent it.
create or replace function public.classroom_invite_info(p_token text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((
    select jsonb_build_object('kind', i.kind, 'org', (select name from cortex_orgs where id = i.org_id), 'valid', i.used_at is null and i.expires_at > now())
    from cortex_invites i where i.token = p_token
  ), jsonb_build_object('valid', false));
$$;

create or replace function public.classroom_invite_accept(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  inv cortex_invites;
begin
  if uid is null then raise exception 'not signed in'; end if;
  select * into inv from cortex_invites where token = p_token for update;
  if inv.token is null or inv.used_at is not null or inv.expires_at <= now() then raise exception 'invite expired'; end if;
  if inv.kind = 'indie' then
    insert into cortex_staff (user_id, role, granted_by) values (uid, 'indie', inv.created_by) on conflict (user_id) do nothing;
  else
    insert into cortex_org_members (org_id, user_id, role)
    values (inv.org_id, uid, case when inv.kind = 'org_admin' then 'admin' else 'teacher' end)
    on conflict (org_id, user_id) do update set role = case when excluded.role = 'admin' then 'admin' else cortex_org_members.role end;
  end if;
  update cortex_invites set used_by = uid, used_at = now() where token = p_token;
  return jsonb_build_object('kind', inv.kind, 'org_id', inv.org_id);
end;
$$;

create or replace function public.classroom_invites_open(p_org uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if (p_org is null and not classroom_is_admin()) or (p_org is not null and not classroom_is_org_admin(p_org)) then
    raise exception 'not an admin';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('token', i.token, 'kind', i.kind, 'note', i.note, 'expires_at', i.expires_at, 'org', (select name from cortex_orgs where id = i.org_id)) order by i.created_at desc)
    from cortex_invites i
    where i.used_at is null and i.expires_at > now()
      and ((p_org is null and i.kind in ('indie','org_admin')) or i.org_id = p_org)
  ), '[]'::jsonb);
end;
$$;

create or replace function public.classroom_invite_revoke(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  inv cortex_invites;
begin
  select * into inv from cortex_invites where token = p_token;
  if inv.token is null then return jsonb_build_object('ok', true); end if;
  if not (classroom_is_admin() or (inv.org_id is not null and classroom_is_org_admin(inv.org_id))) then raise exception 'not an admin'; end if;
  delete from cortex_invites where token = p_token and used_at is null;
  return jsonb_build_object('ok', true);
end;
$$;

-- ── a center (its admins) ───────────────────────────────────────────────

-- "Sắp bỏ học" for the center page, the same rule as packages/classroom-lexica/forecast.ts
-- (THRESHOLDS.dropout): 5 days in a row without study, or, with 3 weeks of history, the last
-- 7 days at half or less of the 3 weeks before (which averaged at least 1 day a week).
create or replace function public.classroom_dropout_risk(p_class uuid, p_user uuid)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare
  t date := cortex_today();
  joined date;
  last_day date;
  w int[];
  avg_before numeric;
begin
  select (joined_at at time zone 'Asia/Ho_Chi_Minh')::date into joined from cortex_class_members where class_id = p_class and user_id = p_user;
  if joined is null then return false; end if;
  select max(date) into last_day from cortex_class_activity_daily where class_id = p_class and user_id = p_user and date <= t;
  if t - coalesce(last_day, joined) >= 5 and t - joined >= 5 then return true; end if;
  if t - joined < 27 then return false; end if;
  select array_agg(n order by k) into w from (
    select k, (select count(distinct date) from cortex_class_activity_daily
               where class_id = p_class and user_id = p_user and date between t - 7 * k - 6 and t - 7 * k)::int as n
    from generate_series(0, 3) k
  ) x;
  avg_before := (w[2] + w[3] + w[4]) / 3.0;
  return avg_before >= 1 and w[1] <= avg_before * 0.5;
end;
$$;

create or replace function public.classroom_org_overview(p_org uuid)
returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
begin
  if not classroom_is_org_admin(p_org) then raise exception 'not an admin'; end if;
  return (
    select jsonb_build_object(
      'id', o.id, 'name', o.name, 'seats', o.seats,
      'used', (select count(distinct m.user_id) from cortex_class_members m join cortex_classes c on c.id = m.class_id where c.org_id = o.id and not c.archived),
      'people', coalesce((
        select jsonb_agg(jsonb_build_object(
          'user_id', m.user_id, 'email', u.email, 'role', m.role,
          'classes', (select count(*) from cortex_classes c where c.org_id = o.id and c.teacher_id = m.user_id and not c.archived)
        ) order by m.role, u.email)
        from cortex_org_members m join auth.users u on u.id = m.user_id where m.org_id = o.id
      ), '[]'::jsonb),
      'classes', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', c.id, 'name', c.name, 'apps', c.apps,
          'teacher', (select email from auth.users where id = c.teacher_id),
          'members', (select count(*) from cortex_class_members where class_id = c.id),
          'active_week', (select count(distinct a.user_id) from cortex_class_activity a where a.class_id = c.id and a.last_active >= cortex_today() - 6),
          'at_risk', (select count(*) from cortex_class_members m where m.class_id = c.id and classroom_dropout_risk(c.id, m.user_id))
        ) order by c.created_at)
        from cortex_classes c where c.org_id = o.id and not c.archived
      ), '[]'::jsonb)
    )
    from cortex_orgs o where o.id = p_org
  );
end;
$$;

-- A center admin removes a teacher (their classes stay, now run by the center's admins).
create or replace function public.classroom_org_remove_member(p_org uuid, p_user uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not classroom_is_org_admin(p_org) then raise exception 'not an admin'; end if;
  if p_user = auth.uid() then raise exception 'not yourself'; end if;
  delete from cortex_org_members where org_id = p_org and user_id = p_user;
  return jsonb_build_object('ok', true);
end;
$$;

-- ── classes ─────────────────────────────────────────────────────────────

-- In a center: any of its members. Outside one: independent teachers and system admins.
create or replace function public.classroom_class_create(p_name text, p_apps text[], p_settings jsonb default '{}', p_org uuid default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  v_apps text[] := classroom_clean_apps(p_apps);
  cid uuid;
  c text;
begin
  if uid is null then raise exception 'not signed in'; end if;
  if p_org is not null then
    if not exists (select 1 from cortex_org_members where org_id = p_org and user_id = uid) then raise exception 'not in this center'; end if;
  elsif not exists (select 1 from cortex_staff where user_id = uid) then
    raise exception 'not a teacher';
  end if;
  if coalesce(array_length(v_apps, 1), 0) = 0 then raise exception 'no apps'; end if;
  c := classroom_code();
  insert into cortex_classes (org_id, teacher_id, name, code, apps, settings, leaderboard_app)
  values (p_org, uid, trim(p_name), c, v_apps, classroom_clean_settings(v_apps, p_settings), v_apps[1])
  returning id into cid;
  return jsonb_build_object('id', cid, 'code', c);
end;
$$;

create or replace function public.classroom_class_update(p_class uuid, p_name text default null, p_apps text[] default null, p_settings jsonb default null,
  p_leaderboard boolean default null, p_leaderboard_app text default null, p_archived boolean default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  cls cortex_classes;
  v_apps text[];
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  select * into cls from cortex_classes where id = p_class;
  v_apps := case when p_apps is null then cls.apps else classroom_clean_apps(p_apps) end;
  if coalesce(array_length(v_apps, 1), 0) = 0 then raise exception 'no apps'; end if;
  update cortex_classes set
    name = coalesce(nullif(trim(p_name), ''), name),
    apps = v_apps,
    -- Settings of apps still on: the new ones where given, else the old ones.
    settings = classroom_clean_settings(v_apps, cls.settings || coalesce(p_settings, '{}'::jsonb)),
    leaderboard = coalesce(p_leaderboard, leaderboard),
    leaderboard_app = case when coalesce(p_leaderboard_app, leaderboard_app) = any(v_apps) then coalesce(p_leaderboard_app, leaderboard_app) else v_apps[1] end,
    archived = coalesce(p_archived, archived)
  where id = p_class;
  return jsonb_build_object('ok', true);
end;
$$;

-- A new code (the old one stops working: for a code that leaked).
create or replace function public.classroom_class_new_code(p_class uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c text := classroom_code();
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  update cortex_classes set code = c where id = p_class;
  return jsonb_build_object('code', c);
end;
$$;

create or replace function public.classroom_class_join(p_code text, p_display_name text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  cls cortex_classes;
  seats int;
  used int;
begin
  if uid is null then raise exception 'not signed in'; end if;
  select * into cls from cortex_classes where code = upper(trim(p_code)) and not archived;
  if cls.id is null then raise exception 'no such class'; end if;
  -- The class's teacher (or the center's admin) teaches it; they do not join it as a student.
  if classroom_can_teach(cls.id) then raise exception 'own class'; end if;
  if exists (select 1 from cortex_class_members where class_id = cls.id and user_id = uid) then
    update cortex_class_members set display_name = trim(p_display_name) where class_id = cls.id and user_id = uid;
    return jsonb_build_object('class_id', cls.id, 'name', cls.name, 'apps', cls.apps);
  end if;
  -- Seats: a center's limit across its classes; an independent teacher gets 60 per class.
  if cls.org_id is not null then
    select o.seats into seats from cortex_orgs o where o.id = cls.org_id;
    select count(distinct m.user_id) into used from cortex_class_members m join cortex_classes c on c.id = m.class_id
    where c.org_id = cls.org_id and not c.archived;
    if used >= seats and not exists (
      select 1 from cortex_class_members m join cortex_classes c on c.id = m.class_id where c.org_id = cls.org_id and m.user_id = uid
    ) then raise exception 'no seats'; end if;
  elsif (select count(*) from cortex_class_members where class_id = cls.id) >= 60 then
    raise exception 'no seats';
  end if;
  insert into cortex_class_members (class_id, user_id, display_name) values (cls.id, uid, trim(p_display_name));
  return jsonb_build_object('class_id', cls.id, 'name', cls.name, 'apps', cls.apps);
end;
$$;

create or replace function public.classroom_class_leave(p_class uuid)
returns jsonb language sql volatile security definer set search_path = public as $$
  with gone as (delete from cortex_class_members where class_id = p_class and user_id = auth.uid() returning 1),
       act as (delete from cortex_class_activity where class_id = p_class and user_id = auth.uid() returning 1)
  select jsonb_build_object('left', (select count(*) from gone) > 0);
$$;

-- Classes the user is in or teaches, with every app's assignments (the code only for teachers).
-- p_app: only classes using this app (a learning app asks for its own).
create or replace function public.classroom_my_classes(p_app text default null)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(item order by item->>'created_at'), '[]'::jsonb) from (
    select jsonb_build_object(
      'id', c.id, 'name', c.name, 'apps', c.apps, 'settings', c.settings,
      'org_id', c.org_id, 'org', (select name from cortex_orgs where id = c.org_id),
      'created_at', c.created_at, 'leaderboard', c.leaderboard, 'leaderboard_app', c.leaderboard_app,
      'role', case when classroom_can_teach(c.id) and not exists (select 1 from cortex_class_members m where m.class_id = c.id and m.user_id = auth.uid()) then 'teacher' else 'student' end,
      'code', case when classroom_can_teach(c.id) then c.code end,
      'members', (select count(*) from cortex_class_members where class_id = c.id),
      'assignments', coalesce((
        select jsonb_agg(jsonb_build_object('id', a.id, 'app', a.app, 'kind', a.kind, 'title', a.title, 'payload', a.payload, 'due_on', a.due_on, 'created_at', a.created_at, 'for_user', a.for_user) order by a.created_at desc)
        from cortex_class_assignments a where a.class_id = c.id and (p_app is null or a.app = p_app)
          and (a.for_user is null or a.for_user = auth.uid() or classroom_can_teach(c.id))
      ), '[]'::jsonb)
    ) as item
    from cortex_classes c
    where not c.archived
      and (p_app is null or p_app = any(c.apps))
      and (
        c.teacher_id = auth.uid()
        or exists (select 1 from cortex_org_members om where om.org_id = c.org_id and om.user_id = auth.uid() and om.role = 'admin')
        or exists (select 1 from cortex_class_members m where m.class_id = c.id and m.user_id = auth.uid())
      )
  ) t;
$$;

-- A student's app reports its own numbers to every class that uses it; the module cleans them per class.
create or replace function public.classroom_report(p_app text, p_metrics jsonb, p_streak int default 0)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  hook text := classroom_hook_name(p_app, 'clean_metrics');
  m record;
  n int := 0;
  clean jsonb;
begin
  if uid is null then return jsonb_build_object('classes', 0); end if;
  if hook is null then raise exception 'app has no clean_metrics'; end if;
  for m in
    select cm.class_id from cortex_class_members cm join cortex_classes c on c.id = cm.class_id
    where cm.user_id = uid and p_app = any(c.apps) and not c.archived
  loop
    execute format('select %I($1, $2)', hook) into clean using m.class_id, coalesce(p_metrics, '{}'::jsonb);
    insert into cortex_class_activity (class_id, user_id, app, metrics, streak, last_active, updated_at)
    values (m.class_id, uid, p_app, clean, least(greatest(coalesce(p_streak, 0), 0), 10000), cortex_today(), now())
    on conflict (class_id, user_id, app) do update set
      metrics = excluded.metrics, streak = excluded.streak, last_active = excluded.last_active, updated_at = now();
    insert into cortex_class_activity_daily (class_id, user_id, app, date, metrics)
    values (m.class_id, uid, p_app, cortex_today(), clean)
    on conflict (class_id, user_id, app, date) do update set metrics = excluded.metrics;
    n := n + 1;
  end loop;
  return jsonb_build_object('classes', n);
end;
$$;

-- The teacher's board: the class, its assignments, each student with every app's numbers now and a week ago.
create or replace function public.classroom_class_board(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  return (
    select jsonb_build_object(
      'class', (
        select jsonb_build_object('id', c.id, 'name', c.name, 'code', c.code, 'apps', c.apps, 'settings', c.settings,
          'leaderboard', c.leaderboard, 'leaderboard_app', c.leaderboard_app, 'org_id', c.org_id, 'created_at', c.created_at,
          'org', (select name from cortex_orgs where id = c.org_id))
        from cortex_classes c where c.id = p_class
      ),
      'assignments', coalesce((
        select jsonb_agg(jsonb_build_object('id', a.id, 'app', a.app, 'kind', a.kind, 'title', a.title, 'payload', a.payload, 'due_on', a.due_on, 'created_at', a.created_at, 'for_user', a.for_user) order by a.created_at desc)
        from cortex_class_assignments a where a.class_id = p_class
      ), '[]'::jsonb),
      'students', coalesce((
        select jsonb_agg(jsonb_build_object(
          'user_id', m.user_id,
          'name', m.display_name,
          'joined_at', m.joined_at,
          'note', m.note,
          'streak', coalesce((select max(streak) from cortex_class_activity a where a.class_id = p_class and a.user_id = m.user_id), 0),
          'last_active', (select max(last_active) from cortex_class_activity a where a.class_id = p_class and a.user_id = m.user_id),
          'inactive_days', (select cortex_today() - max(last_active) from cortex_class_activity a where a.class_id = p_class and a.user_id = m.user_id),
          'days', (
            select coalesce(jsonb_agg(distinct d.date), '[]'::jsonb) from cortex_class_activity_daily d
            where d.class_id = p_class and d.user_id = m.user_id and d.date > cortex_today() - 30
          ),
          'apps', coalesce((
            select jsonb_object_agg(a.app, jsonb_build_object(
              'metrics', a.metrics,
              'last_active', a.last_active,
              'week_ago', (select d.metrics from cortex_class_activity_daily d where d.class_id = p_class and d.user_id = m.user_id and d.app = a.app and d.date <= cortex_today() - 7 order by d.date desc limit 1),
              'week_first', (select d.metrics from cortex_class_activity_daily d where d.class_id = p_class and d.user_id = m.user_id and d.app = a.app and d.date > cortex_today() - 7 order by d.date asc limit 1)
            ))
            from cortex_class_activity a where a.class_id = p_class and a.user_id = m.user_id
          ), '{}'::jsonb)
        ) order by m.display_name)
        from cortex_class_members m where m.class_id = p_class
      ), '[]'::jsonb)
    )
  );
end;
$$;

-- Students see the ranking only when the teacher turned it on; the module scores it.
create or replace function public.classroom_class_leaderboard(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  cls cortex_classes;
  hook text;
  out jsonb;
begin
  if not (classroom_can_teach(p_class) or exists (select 1 from cortex_class_members where class_id = p_class and user_id = auth.uid())) then
    raise exception 'not in this class';
  end if;
  select * into cls from cortex_classes where id = p_class;
  if not classroom_can_teach(p_class) and not cls.leaderboard then return '[]'::jsonb; end if;
  hook := classroom_hook_name(cls.leaderboard_app, 'rank');
  if hook is null then return '[]'::jsonb; end if;
  execute format($q$
    select coalesce(jsonb_agg(jsonb_build_object('name', r.name, 'score', r.score, 'me', r.me) order by r.score desc, r.name), '[]'::jsonb)
    from (
      select m.display_name as name, coalesce(%I(a.metrics), 0) as score, m.user_id = auth.uid() as me
      from cortex_class_members m
      left join cortex_class_activity a on a.class_id = m.class_id and a.user_id = m.user_id and a.app = $2
      where m.class_id = $1
    ) r
  $q$, hook) into out using p_class, cls.leaderboard_app;
  return out;
end;
$$;

-- Giving work: the app must be on for the class; its module cleans the payload, then may act on it.
create or replace function public.classroom_assign(p_class uuid, p_app text, p_kind text, p_title text, p_payload jsonb, p_due date default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  clean_hook text := classroom_hook_name(p_app, 'clean_payload');
  after_hook text := classroom_hook_name(p_app, 'after_assign');
  clean jsonb;
  aid uuid;
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if not exists (select 1 from cortex_classes where id = p_class and p_app = any(apps)) then raise exception 'app not in class'; end if;
  if clean_hook is null then raise exception 'app has no clean_payload'; end if;
  execute format('select %I($1, $2)', clean_hook) into clean using p_kind, coalesce(p_payload, '{}'::jsonb);
  insert into cortex_class_assignments (class_id, app, kind, title, payload, due_on, created_by)
  values (p_class, p_app, p_kind, trim(p_title), clean, p_due, auth.uid()) returning id into aid;
  if after_hook is not null then execute format('select %I($1, $2, $3)', after_hook) using p_class, aid, clean; end if;
  return jsonb_build_object('id', aid, 'payload', clean);
end;
$$;

-- Giving work to one student of the class (W4 "Giao ôn lại"): same checks as classroom_assign.
create or replace function public.classroom_assign_to(p_class uuid, p_user uuid, p_app text, p_kind text, p_title text, p_payload jsonb, p_due date default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  clean_hook text := classroom_hook_name(p_app, 'clean_payload');
  after_hook text := classroom_hook_name(p_app, 'after_assign');
  clean jsonb;
  aid uuid;
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if not exists (select 1 from cortex_class_members where class_id = p_class and user_id = p_user) then raise exception 'not in this class'; end if;
  if not exists (select 1 from cortex_classes where id = p_class and p_app = any(apps)) then raise exception 'app not in class'; end if;
  if clean_hook is null then raise exception 'app has no clean_payload'; end if;
  execute format('select %I($1, $2)', clean_hook) into clean using p_kind, coalesce(p_payload, '{}'::jsonb);
  insert into cortex_class_assignments (class_id, app, kind, title, payload, due_on, created_by, for_user)
  values (p_class, p_app, p_kind, trim(p_title), clean, p_due, auth.uid(), p_user) returning id into aid;
  if after_hook is not null then execute format('select %I($1, $2, $3)', after_hook) using p_class, aid, clean; end if;
  return jsonb_build_object('id', aid, 'payload', clean);
end;
$$;

create or replace function public.classroom_assignment_update(p_assignment uuid, p_title text default null, p_due date default null, p_clear_due boolean default false, p_payload jsonb default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  a cortex_class_assignments;
  clean jsonb;
begin
  select * into a from cortex_class_assignments where id = p_assignment;
  if a.id is null or not classroom_can_teach(a.class_id) then raise exception 'not the teacher'; end if;
  if p_payload is not null then
    execute format('select %I($1, $2)', classroom_hook_name(a.app, 'clean_payload')) into clean using a.kind, a.payload || p_payload;
  end if;
  update cortex_class_assignments set
    title = coalesce(nullif(trim(p_title), ''), title),
    due_on = case when p_clear_due then null else coalesce(p_due, due_on) end,
    payload = coalesce(clean, payload)
  where id = p_assignment;
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.classroom_unassign(p_assignment uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  cid uuid;
begin
  select class_id into cid from cortex_class_assignments where id = p_assignment;
  if cid is null or not classroom_can_teach(cid) then raise exception 'not the teacher'; end if;
  delete from cortex_class_assignments where id = p_assignment;
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.classroom_member_update(p_class uuid, p_user uuid, p_note text default null, p_remove boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if p_remove then
    delete from cortex_class_activity where class_id = p_class and user_id = p_user;
    delete from cortex_class_members where class_id = p_class and user_id = p_user;
  else
    update cortex_class_members set note = nullif(trim(p_note), '') where class_id = p_class and user_id = p_user;
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- ── grants ──────────────────────────────────────────────────────────────

do $$
declare f text;
begin
  foreach f in array array[
    'classroom_whoami()', 'classroom_org_create(text)', 'classroom_org_update(uuid, text, int)', 'classroom_admin_overview()',
    'classroom_indie_revoke(uuid)', 'classroom_invite_create(text, uuid, text, int)', 'classroom_invite_accept(text)',
    'classroom_invites_open(uuid)', 'classroom_invite_revoke(text)', 'classroom_org_overview(uuid)', 'classroom_org_remove_member(uuid, uuid)',
    'classroom_class_create(text, text[], jsonb, uuid)', 'classroom_class_update(uuid, text, text[], jsonb, boolean, text, boolean)',
    'classroom_class_new_code(uuid)', 'classroom_class_join(text, text)', 'classroom_class_leave(uuid)', 'classroom_my_classes(text)',
    'classroom_report(text, jsonb, int)', 'classroom_class_board(uuid)', 'classroom_class_leaderboard(uuid)',
    'classroom_assign(uuid, text, text, text, jsonb, date)', 'classroom_assign_to(uuid, uuid, text, text, text, jsonb, date)', 'classroom_assignment_update(uuid, text, date, boolean, jsonb)',
    'classroom_unassign(uuid)', 'classroom_member_update(uuid, uuid, text, boolean)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  revoke all on function public.classroom_invite_info(text) from public;
  grant execute on function public.classroom_invite_info(text) to anon, authenticated;
  foreach f in array array['classroom_is_admin()', 'classroom_is_org_admin(uuid)', 'classroom_can_teach(uuid)',
    'classroom_hook_name(text, text)', 'classroom_clean_apps(text[])', 'classroom_clean_settings(text[], jsonb)', 'classroom_code()',
    'classroom_dropout_risk(uuid, uuid)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- packages/classroom/sql/classroom_parents.sql
-- ============================================================

-- Parents (docs/TEACH_PLAN.md, section 3, T4): a private link per student, and
-- a weekly report the teacher reviews and approves before parents see it.
-- Runs after classroom_core.sql. Safe to re-run.
--
-- A parent needs no account: they open teach/p/<code> (12 characters, about
-- 59 bits), plus a 4-digit PIN when the class turns PINs on. Five wrong PINs
-- lock the link for 15 minutes. Parents only ever read approved reports, never
-- the teacher's private note on the student. Every read and write goes
-- through the functions below; the tables have RLS on and no policies.

alter table cortex_classes add column if not exists parent_pin boolean not null default false;

create table if not exists cortex_parent_links (
  code text primary key check (code ~ '^[a-z2-9]{12}$'),
  class_id uuid not null references cortex_classes(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  pin_salt text,
  pin_hash text,
  fails int not null default 0,
  locked_until timestamptz,
  created_at timestamptz not null default now(),
  revoked_at timestamptz
);
-- One live link per student per class
create unique index if not exists cortex_parent_links_live_idx on cortex_parent_links (class_id, user_id) where revoked_at is null;

-- One approved report per student per week (week = the Monday it starts on).
create table if not exists cortex_weekly_reports (
  class_id uuid not null references cortex_classes(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  week date not null check (extract(isodow from week) = 1),
  content jsonb not null,
  approved_by uuid references auth.users(id) on delete set null,
  approved_at timestamptz not null default now(),
  opens int not null default 0,
  first_opened_at timestamptz,
  primary key (class_id, user_id, week)
);

alter table cortex_parent_links enable row level security;
alter table cortex_weekly_reports enable row level security;

-- ── helpers ─────────────────────────────────────────────────────────────

-- 12 characters without look-alikes (no 0 o 1 l i), from a random uuid's bytes.
create or replace function public.cortex_parent_code()
returns text language plpgsql volatile as $$
declare
  alphabet constant text := 'abcdefghjkmnpqrstuvwxyz23456789';
  b bytea := decode(replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''), 'hex');
  out text := '';
begin
  for i in 0..11 loop
    out := out || substr(alphabet, get_byte(b, i) % 31 + 1, 1);
  end loop;
  return out;
end;
$$;

create or replace function public.cortex_pin_hash(p_salt text, p_pin text)
returns text language sql immutable as $$
  select encode(sha256(convert_to(p_salt || ':' || p_pin, 'UTF8')), 'hex');
$$;

-- What a report may hold (packages/classroom/parents.ts, ReportContent): short
-- Vietnamese text and a few numbers. Anything else is dropped.
create or replace function public.cortex_clean_report(p jsonb)
returns jsonb language plpgsql immutable as $$
declare
  did jsonb;
  score jsonb;
  attend jsonb;
  t text;
begin
  if jsonb_typeof(p) <> 'object' then raise exception 'bad report'; end if;
  t := left(trim(coalesce(p->>'summary', '')), 400);
  if t = '' then raise exception 'bad report'; end if;
  select coalesce(jsonb_agg(item), '[]') into did from (
    select jsonb_strip_nulls(jsonb_build_object(
      'text', left(trim(x->>'text'), 200),
      'words', (select jsonb_agg(left(w, 40)) from (select jsonb_array_elements_text(case when jsonb_typeof(x->'words') = 'array' then x->'words' else '[]' end) w limit 8) ws)
    )) as item
    from jsonb_array_elements(case when jsonb_typeof(p->'did') = 'array' then p->'did' else '[]' end) x
    where jsonb_typeof(x) = 'object' and coalesce(trim(x->>'text'), '') <> ''
    limit 3
  ) d;
  if jsonb_typeof(p->'score') = 'object' and jsonb_typeof(p->'score'->'score') = 'number' then
    score := jsonb_strip_nulls(jsonb_build_object(
      'score', least(greatest(round((p->'score'->>'score')::numeric), 0), 3000)::int,
      'ielts', left(p->'score'->>'ielts', 12),
      'delta', case when jsonb_typeof(p->'score'->'delta') = 'number' then least(greatest(round((p->'score'->>'delta')::numeric), -3000), 3000)::int end,
      'at', case when (p->'score'->>'at') ~ '^\d{4}-\d{2}-\d{2}' then left(p->'score'->>'at', 10) end
    ));
  end if;
  -- Lessons in class that week (classroom_attendance.sql): held, came (on time or late), late, excused
  if jsonb_typeof(p->'attend') = 'object' and jsonb_typeof(p->'attend'->'held') = 'number' and (p->'attend'->>'held')::numeric >= 1 then
    attend := jsonb_strip_nulls(jsonb_build_object(
      'held', least(round((p->'attend'->>'held')::numeric), 14)::int,
      'came', case when jsonb_typeof(p->'attend'->'came') = 'number' then least(greatest(round((p->'attend'->>'came')::numeric), 0), least(round((p->'attend'->>'held')::numeric), 14))::int else 0 end,
      'late', case when jsonb_typeof(p->'attend'->'late') = 'number' then nullif(least(greatest(round((p->'attend'->>'late')::numeric), 0), 14)::int, 0) end,
      'excused', case when jsonb_typeof(p->'attend'->'excused') = 'number' then nullif(least(greatest(round((p->'attend'->>'excused')::numeric), 0), 14)::int, 0) end
    ));
  end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'v', 1,
    'days', case when jsonb_typeof(p->'days') = 'number' then least(greatest(round((p->>'days')::numeric), 0), 7)::int else 0 end,
    'summary', t,
    'did', did,
    'attend', attend,
    'score', score,
    'help', nullif(left(trim(coalesce(p->>'help', '')), 300), ''),
    'note', nullif(left(trim(coalesce(p->>'note', '')), 500), '')
  ));
end;
$$;

-- ── teacher ─────────────────────────────────────────────────────────────

-- The class's parent page state: PIN on or off, each student's live link, and the week's reports.
create or replace function public.classroom_parents(p_class uuid, p_week date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  return jsonb_build_object(
    'pin', (select parent_pin from cortex_classes where id = p_class),
    'links', coalesce((
      select jsonb_object_agg(l.user_id, jsonb_build_object('code', l.code, 'pin', l.pin_hash is not null, 'created_at', l.created_at))
      from cortex_parent_links l where l.class_id = p_class and l.revoked_at is null
    ), '{}'::jsonb),
    'reports', coalesce((
      select jsonb_object_agg(r.user_id, jsonb_build_object('content', r.content, 'approved_at', r.approved_at, 'opens', r.opens, 'first_opened_at', r.first_opened_at))
      from cortex_weekly_reports r where r.class_id = p_class and r.week = p_week
    ), '{}'::jsonb)
  );
end;
$$;

create or replace function public.classroom_parent_pin_set(p_class uuid, p_on boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  update cortex_classes set parent_pin = coalesce(p_on, false) where id = p_class;
  return jsonb_build_object('ok', true);
end;
$$;

-- A new link for a student's parents (the old one stops working). The PIN, when the
-- class uses PINs, is returned this once; only its hash is kept.
create or replace function public.classroom_parent_link_new(p_class uuid, p_user uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c text;
  pin text;
  salt text;
  b bytea;
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if not exists (select 1 from cortex_class_members where class_id = p_class and user_id = p_user) then raise exception 'not in this class'; end if;
  update cortex_parent_links set revoked_at = now() where class_id = p_class and user_id = p_user and revoked_at is null;
  loop
    c := cortex_parent_code();
    exit when not exists (select 1 from cortex_parent_links where code = c);
  end loop;
  if (select parent_pin from cortex_classes where id = p_class) then
    b := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    pin := lpad(((get_byte(b, 0) * 256 + get_byte(b, 1)) % 10000)::text, 4, '0');
    salt := replace(gen_random_uuid()::text, '-', '');
  end if;
  insert into cortex_parent_links (code, class_id, user_id, pin_salt, pin_hash)
  values (c, p_class, p_user, salt, case when pin is not null then cortex_pin_hash(salt, pin) end);
  return jsonb_strip_nulls(jsonb_build_object('code', c, 'pin', pin));
end;
$$;

create or replace function public.classroom_parent_link_revoke(p_class uuid, p_user uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  update cortex_parent_links set revoked_at = now() where class_id = p_class and user_id = p_user and revoked_at is null;
  return jsonb_build_object('ok', true);
end;
$$;

-- A finished week's numbers per student and app: the last report on or before
-- the week's Sunday (`end`) and before its Monday (`start`), and the days studied.
-- The same answer whichever day the teacher asks.
create or replace function public.classroom_week_metrics(p_class uuid, p_week date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if extract(isodow from p_week) <> 1 then raise exception 'week starts on Monday'; end if;
  return coalesce((
    select jsonb_object_agg(m.user_id, jsonb_build_object(
      'days', (
        select coalesce(jsonb_agg(distinct d.date), '[]'::jsonb) from cortex_class_activity_daily d
        where d.class_id = p_class and d.user_id = m.user_id and d.date between p_week and p_week + 6
      ),
      'apps', coalesce((
        select jsonb_object_agg(a.app, jsonb_build_object(
          'end', (select d.metrics from cortex_class_activity_daily d where d.class_id = p_class and d.user_id = m.user_id and d.app = a.app and d.date <= p_week + 6 order by d.date desc limit 1),
          'start', (select d.metrics from cortex_class_activity_daily d where d.class_id = p_class and d.user_id = m.user_id and d.app = a.app and d.date < p_week order by d.date desc limit 1)
        ))
        from (select distinct app from cortex_class_activity_daily where class_id = p_class and user_id = m.user_id) a
      ), '{}'::jsonb)
    ))
    from cortex_class_members m where m.class_id = p_class
  ), '{}'::jsonb);
end;
$$;

-- The teacher approves a student's report for a week; approving again replaces it (opens are kept).
create or replace function public.classroom_report_approve(p_class uuid, p_user uuid, p_week date, p_content jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  clean jsonb;
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if not exists (select 1 from cortex_class_members where class_id = p_class and user_id = p_user) then raise exception 'not in this class'; end if;
  if extract(isodow from p_week) <> 1 or p_week > cortex_today() then raise exception 'week starts on Monday'; end if;
  clean := cortex_clean_report(p_content);
  insert into cortex_weekly_reports (class_id, user_id, week, content, approved_by, approved_at)
  values (p_class, p_user, p_week, clean, auth.uid(), now())
  on conflict (class_id, user_id, week) do update set content = excluded.content, approved_by = excluded.approved_by, approved_at = now();
  return jsonb_build_object('ok', true, 'content', clean);
end;
$$;

-- ── parents (no account) ────────────────────────────────────────────────

-- What a parent sees: the student's name in class, the class, and the approved
-- reports, newest first (12 weeks). Opening counts as a view of the newest.
create or replace function public.parent_view(p_code text, p_pin text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  l cortex_parent_links;
  latest date;
  tries int;
begin
  select * into l from cortex_parent_links where code = lower(trim(p_code)) and revoked_at is null;
  if l.code is null then raise exception 'link not found'; end if;
  if l.pin_hash is not null then
    if l.locked_until is not null and l.locked_until > now() then raise exception 'link locked'; end if;
    if p_pin is null or p_pin = '' then return jsonb_build_object('need_pin', true); end if;
    if cortex_pin_hash(l.pin_salt, trim(p_pin)) <> l.pin_hash then
      -- A lock that has run out starts the count again
      tries := case when l.locked_until is not null then 1 else l.fails + 1 end;
      update cortex_parent_links set fails = tries,
        locked_until = case when tries >= 5 then now() + interval '15 minutes' end
      where code = l.code;
      -- Not an exception: the failed try must be kept
      return jsonb_build_object('need_pin', true, 'wrong', true, 'locked', tries >= 5);
    end if;
    update cortex_parent_links set fails = 0, locked_until = null where code = l.code;
  end if;
  select max(week) into latest from cortex_weekly_reports where class_id = l.class_id and user_id = l.user_id;
  if latest is not null then
    update cortex_weekly_reports set opens = opens + 1, first_opened_at = coalesce(first_opened_at, now())
    where class_id = l.class_id and user_id = l.user_id and week = latest;
  end if;
  return jsonb_build_object(
    'name', (select display_name from cortex_class_members where class_id = l.class_id and user_id = l.user_id),
    'class', (select name from cortex_classes where id = l.class_id),
    'reports', coalesce((
      select jsonb_agg(jsonb_build_object('week', r.week, 'content', r.content) order by r.week desc)
      from (select * from cortex_weekly_reports where class_id = l.class_id and user_id = l.user_id order by week desc limit 12) r
    ), '[]'::jsonb)
  );
end;
$$;

do $$
declare f text;
begin
  foreach f in array array['classroom_parents(uuid, date)', 'classroom_parent_pin_set(uuid, boolean)', 'classroom_parent_link_new(uuid, uuid)',
    'classroom_parent_link_revoke(uuid, uuid)', 'classroom_week_metrics(uuid, date)', 'classroom_report_approve(uuid, uuid, date, jsonb)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  revoke all on function public.parent_view(text, text) from public;
  grant execute on function public.parent_view(text, text) to anon, authenticated;
  foreach f in array array['cortex_parent_code()', 'cortex_pin_hash(text, text)', 'cortex_clean_report(jsonb)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- packages/classroom/sql/classroom_attendance.sql
-- ============================================================

-- Class sessions and attendance (Teach "Buổi học"): the weekly timetable, and
-- who came to each lesson. Runs after classroom_core.sql. Safe to re-run.
--
-- A class has a weekly schedule (days and a start time). A session is one class
-- day: it exists once the teacher takes the roll, writes what the lesson was
-- about, or cancels it (a holiday). One session per class per day. Marks are
-- per student: present, late, absent, excused (absent with a reason).
-- Only the class's teachers read or write them; students and parents see the
-- roll only through an approved weekly report. Every read and write goes
-- through the functions below; the tables have RLS on and no policies.

alter table cortex_classes add column if not exists schedule jsonb not null default '[]'::jsonb;

create table if not exists cortex_class_sessions (
  class_id uuid not null references cortex_classes(id) on delete cascade,
  on_date date not null,
  topic text check (topic is null or char_length(topic) <= 120),
  cancelled boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (class_id, on_date)
);

create table if not exists cortex_attendance (
  class_id uuid not null,
  on_date date not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  status text not null check (status in ('present', 'late', 'absent', 'excused')),
  marked_by uuid references auth.users(id) on delete set null,
  marked_at timestamptz not null default now(),
  primary key (class_id, on_date, user_id),
  foreign key (class_id, on_date) references cortex_class_sessions(class_id, on_date) on delete cascade
);
create index if not exists cortex_attendance_user_idx on cortex_attendance (class_id, user_id, on_date);

alter table cortex_class_sessions enable row level security;
alter table cortex_attendance enable row level security;

-- ── helpers ─────────────────────────────────────────────────────────────

-- A timetable as packages/classroom/attendance.ts reads it: at most one slot per
-- weekday (ISO, Monday 1), a start "HH:MM" and a length of 15 to 300 minutes.
-- Bad slots are dropped, not rejected.
create or replace function public.cortex_clean_schedule(p jsonb)
returns jsonb language sql immutable as $$
  select coalesce(jsonb_agg(jsonb_build_object('dow', dow, 'start', start, 'minutes', minutes) order by dow), '[]'::jsonb)
  from (
    select distinct on (dow) dow, start, minutes from (
      select (x->>'dow')::int as dow,
             x->>'start' as start,
             least(greatest(coalesce(round((x->>'minutes')::numeric)::int, 90), 15), 300) as minutes
      from jsonb_array_elements(case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) x
      where jsonb_typeof(x) = 'object'
        and coalesce(x->>'dow', '') ~ '^[1-7]$'
        and coalesce(x->>'start', '') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        and (x->'minutes' is null or jsonb_typeof(x->'minutes') = 'number')
    ) s
    order by dow, start
  ) d;
$$;

-- One session as Teach reads it: its date, topic, whether it was cancelled, and the marks by student.
create or replace function public.cortex_session_json(p_class uuid, p_date date)
returns jsonb language sql stable as $$
  select jsonb_build_object(
    'date', s.on_date,
    'topic', s.topic,
    'cancelled', s.cancelled,
    'marks', coalesce((select jsonb_object_agg(a.user_id, a.status) from cortex_attendance a where a.class_id = s.class_id and a.on_date = s.on_date), '{}'::jsonb)
  )
  from cortex_class_sessions s where s.class_id = p_class and s.on_date = p_date;
$$;

-- ── teacher ─────────────────────────────────────────────────────────────

create or replace function public.classroom_schedule_set(p_class uuid, p_schedule jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  clean jsonb := cortex_clean_schedule(p_schedule);
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  update cortex_classes set schedule = clean where id = p_class;
  return jsonb_build_object('schedule', clean);
end;
$$;

-- The timetable and sessions between two dates for each class asked for that
-- this person teaches (others are left out): one call for the Today page.
create or replace function public.classroom_attendance(p_classes uuid[], p_from date, p_to date)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then raise exception 'bad date range'; end if;
  if coalesce(array_length(p_classes, 1), 0) > 100 then raise exception 'bad date range'; end if;
  return coalesce((
    select jsonb_object_agg(c.id, jsonb_build_object(
      'schedule', c.schedule,
      'sessions', coalesce((
        select jsonb_agg(cortex_session_json(c.id, s.on_date) order by s.on_date desc)
        from cortex_class_sessions s where s.class_id = c.id and s.on_date between p_from and p_to
      ), '[]'::jsonb)
    ))
    from cortex_classes c
    where c.id = any(p_classes) and classroom_can_teach(c.id)
  ), '{}'::jsonb);
end;
$$;

-- Take the roll for a day (today or up to 120 days back): `p_marks` maps a
-- student to a status, or to null to clear their mark. Students no longer in
-- the class are skipped. Marking a cancelled day reopens it. `p_topic` (when
-- given; '' clears it) is what the lesson was about.
create or replace function public.classroom_attendance_mark(p_class uuid, p_date date, p_marks jsonb, p_topic text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if p_date is null or p_date > cortex_today() or p_date < cortex_today() - 120 then raise exception 'bad session date'; end if;
  if jsonb_typeof(coalesce(p_marks, '{}'::jsonb)) <> 'object' then raise exception 'bad attendance'; end if;

  insert into cortex_class_sessions (class_id, on_date, topic)
  values (p_class, p_date, nullif(left(trim(coalesce(p_topic, '')), 120), ''))
  on conflict (class_id, on_date) do update set
    cancelled = false,
    topic = case when p_topic is null then cortex_class_sessions.topic else excluded.topic end,
    updated_at = now();

  delete from cortex_attendance a
  using jsonb_each(coalesce(p_marks, '{}'::jsonb)) m
  where a.class_id = p_class and a.on_date = p_date and a.user_id::text = m.key and jsonb_typeof(m.value) = 'null';

  insert into cortex_attendance (class_id, on_date, user_id, status, marked_by)
  select p_class, p_date, mem.user_id, m.value #>> '{}', auth.uid()
  from jsonb_each(coalesce(p_marks, '{}'::jsonb)) m
  join cortex_class_members mem on mem.class_id = p_class and mem.user_id::text = m.key
  where jsonb_typeof(m.value) = 'string' and m.value #>> '{}' in ('present', 'late', 'absent', 'excused')
  on conflict (class_id, on_date, user_id) do update set status = excluded.status, marked_by = excluded.marked_by, marked_at = now();

  return cortex_session_json(p_class, p_date);
end;
$$;

-- What a day's lesson was about, or cancel it (a holiday: its marks are
-- dropped). Up to 120 days either side of today. A day left with no topic, no
-- marks and not cancelled is removed, so it is a plain timetable day again.
create or replace function public.classroom_session_set(p_class uuid, p_date date, p_topic text, p_cancelled boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if p_date is null or abs(p_date - cortex_today()) > 120 then raise exception 'bad session date'; end if;

  insert into cortex_class_sessions (class_id, on_date, topic, cancelled)
  values (p_class, p_date, nullif(left(trim(coalesce(p_topic, '')), 120), ''), coalesce(p_cancelled, false))
  on conflict (class_id, on_date) do update set
    topic = case when p_topic is null then cortex_class_sessions.topic else excluded.topic end,
    cancelled = coalesce(p_cancelled, cortex_class_sessions.cancelled),
    updated_at = now();
  if coalesce(p_cancelled, false) then
    delete from cortex_attendance where class_id = p_class and on_date = p_date;
  end if;
  delete from cortex_class_sessions s
  where s.class_id = p_class and s.on_date = p_date and not s.cancelled and s.topic is null
    and not exists (select 1 from cortex_attendance a where a.class_id = p_class and a.on_date = p_date);

  return coalesce(cortex_session_json(p_class, p_date), jsonb_build_object('date', p_date, 'topic', null, 'cancelled', false, 'marks', '{}'::jsonb));
end;
$$;

do $$
declare f text;
begin
  foreach f in array array['classroom_schedule_set(uuid, jsonb)', 'classroom_attendance(uuid[], date, date)',
    'classroom_attendance_mark(uuid, date, jsonb, text)', 'classroom_session_set(uuid, date, text, boolean)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['cortex_clean_schedule(jsonb)', 'cortex_session_json(uuid, date)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- packages/classroom/sql/classroom_arena.sql
-- ============================================================

-- "Đấu trường từ vựng" (docs/TEACH_PLAN.md, section 4, T2a): a live quiz the
-- teacher runs on the projector, students answer on their phones in Lexica.
-- Runs after classroom_core.sql. Safe to re-run.
--
-- The server is the referee: questions and answers sit in tables only these
-- functions read; a student gets a question without its answer until the
-- teacher locks it; answers are timed and scored by the server's clock, and
-- refused once the time is up or the question is locked. The teacher's screen
-- drives the room (open, next question, lock, finish); Supabase Realtime only
-- carries "something changed" signals, never answers.
--
-- Rooms: one live room per class (opening a new one finishes the old), a
-- 6-digit code, 3 to 30 questions, 10 to 60 seconds each. Players are the
-- class's students. Modes: classic (everyone for themselves) and team (2–4
-- teams the teacher balances; a team's score is its members' average, so a
-- weaker student still adds to it). When the room finishes, each player's
-- answers stay readable to them (arena_my_results) so Lexica can put the
-- words they missed back into review. Every read and write goes through the functions below;
-- the tables have RLS on and no policies.

create table if not exists cortex_arena_rooms (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references cortex_classes(id) on delete cascade,
  code text not null check (code ~ '^[0-9]{6}$'),
  host uuid references auth.users(id) on delete set null,
  mode text not null default 'classic',
  seconds int not null check (seconds between 10 and 60),
  -- Only the top 3 by name on the projector; the rest see their own rank on their phone
  hide_names boolean not null default true,
  state text not null default 'lobby' check (state in ('lobby', 'question', 'reveal', 'finished')),
  q_index int not null default -1,
  q_opened_at timestamptz,
  created_at timestamptz not null default now(),
  finished_at timestamptz
);
-- A code is unique among rooms still running
-- Added with team mode (T2b)
alter table cortex_arena_rooms add column if not exists teams int not null default 0;
alter table cortex_arena_rooms drop constraint if exists cortex_arena_rooms_mode_check;
alter table cortex_arena_rooms add constraint cortex_arena_rooms_mode_check check (mode in ('classic', 'team') and teams between 0 and 4 and (mode = 'classic') = (teams = 0));
create unique index if not exists cortex_arena_rooms_code_idx on cortex_arena_rooms (code) where state <> 'finished';
create index if not exists cortex_arena_rooms_class_idx on cortex_arena_rooms (class_id, created_at desc);

create table if not exists cortex_arena_questions (
  room_id uuid not null references cortex_arena_rooms(id) on delete cascade,
  idx int not null,
  card_id text,
  kind text not null,
  prompt text not null,
  options jsonb not null,
  answer int not null,
  primary key (room_id, idx)
);

create table if not exists cortex_arena_players (
  room_id uuid not null references cortex_arena_rooms(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  score int not null default 0,
  streak int not null default 0,
  joined_at timestamptz not null default now(),
  primary key (room_id, user_id)
);

alter table cortex_arena_players add column if not exists team int check (team between 1 and 4);

create table if not exists cortex_arena_answers (
  room_id uuid not null references cortex_arena_rooms(id) on delete cascade,
  idx int not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  choice int not null,
  correct boolean not null,
  ms int not null,
  points int not null,
  at timestamptz not null default now(),
  primary key (room_id, idx, user_id)
);

alter table cortex_arena_rooms enable row level security;
alter table cortex_arena_questions enable row level security;
alter table cortex_arena_players enable row level security;
alter table cortex_arena_answers enable row level security;

-- ── helpers ─────────────────────────────────────────────────────────────

-- Late answers: a little grace for the network, on top of the question's time.
create or replace function public.cortex_arena_grace()
returns interval language sql immutable as $$ select interval '1500 milliseconds' $$;

-- Points for a right answer: 1000 at once, down to 500 at the last second,
-- plus 50 for each right answer in a row before it (up to 200). Wrong: 0.
create or replace function public.cortex_arena_points(p_correct boolean, p_ms int, p_seconds int, p_streak int)
returns int language sql immutable as $$
  select case when not p_correct then 0
    else round(1000 * (1 - 0.5 * least(greatest(p_ms, 0), p_seconds * 1000)::numeric / (p_seconds * 1000)))::int + 50 * least(greatest(p_streak, 0), 4)
  end;
$$;

-- The room's ranking: score, then who joined first. `rank` starts at 1; ties share it.
create or replace function public.cortex_arena_ranking(p_room uuid)
returns table (user_id uuid, name text, score int, rank int) language sql stable as $$
  select p.user_id, p.name, p.score, (rank() over (order by p.score desc))::int
  from cortex_arena_players p where p.room_id = p_room
  order by p.score desc, p.joined_at;
$$;

-- Each team's score (its members' average, rounded), size and rank; empty outside team mode.
create or replace function public.cortex_arena_teams(p_room uuid)
returns table (team int, members int, score int, rank int) language sql stable as $$
  select t.team, t.members, t.score, (rank() over (order by t.score desc))::int
  from (
    select p.team, count(*)::int as members, round(avg(p.score))::int as score
    from cortex_arena_players p where p.room_id = p_room and p.team is not null
    group by p.team
  ) t
  order by t.score desc, t.team;
$$;

-- The team with the fewest players (the lowest number on a tie), for someone without one.
create or replace function public.cortex_arena_smallest_team(p_room uuid)
returns int language sql stable as $$
  select g from generate_series(1, (select teams from cortex_arena_rooms where id = p_room)) g
  order by (select count(*) from cortex_arena_players p where p.room_id = p_room and p.team = g), g
  limit 1;
$$;

-- Questions a teacher sends: 3–30 objects {card_id?, kind, prompt, options[2..4], answer}. Bad ones are refused.
create or replace function public.cortex_arena_clean_questions(p jsonb)
returns jsonb language plpgsql immutable as $$
declare
  out jsonb := '[]'::jsonb;
  q jsonb;
  opts jsonb;
  n int;
begin
  if jsonb_typeof(p) <> 'array' or jsonb_array_length(p) < 3 or jsonb_array_length(p) > 30 then raise exception 'bad questions'; end if;
  for q in select * from jsonb_array_elements(p) loop
    if jsonb_typeof(q) <> 'object' or jsonb_typeof(q->'options') <> 'array' or jsonb_typeof(q->'answer') <> 'number' then raise exception 'bad questions'; end if;
    select jsonb_agg(left(trim(o), 80)) into opts from jsonb_array_elements_text(q->'options') o;
    n := coalesce(jsonb_array_length(opts), 0);
    if n < 2 or n > 4 or (select count(distinct lower(x)) from jsonb_array_elements_text(opts) x where x <> '') <> n then raise exception 'bad questions'; end if;
    if (q->>'answer')::numeric <> floor((q->>'answer')::numeric) or (q->>'answer')::int not between 0 and n - 1 then raise exception 'bad questions'; end if;
    if coalesce(trim(q->>'prompt'), '') = '' then raise exception 'bad questions'; end if;
    out := out || jsonb_build_array(jsonb_build_object(
      'card_id', left(q->>'card_id', 64),
      'kind', left(coalesce(q->>'kind', 'meaning'), 20),
      'prompt', left(trim(q->>'prompt'), 200),
      'options', opts,
      'answer', (q->>'answer')::int
    ));
  end loop;
  return out;
end;
$$;

create or replace function public.cortex_arena_room_teach(p_room uuid)
returns cortex_arena_rooms language plpgsql stable security definer set search_path = public as $$
declare
  r cortex_arena_rooms;
begin
  select * into r from cortex_arena_rooms where id = p_room;
  if r.id is null then raise exception 'no such room'; end if;
  if not classroom_can_teach(r.class_id) then raise exception 'not the teacher'; end if;
  return r;
end;
$$;

-- ── teacher ─────────────────────────────────────────────────────────────

-- Open a room for the class with these questions; a room still running in the class is finished first.
drop function if exists public.arena_open(uuid, int, jsonb, boolean);
create or replace function public.arena_open(p_class uuid, p_seconds int, p_questions jsonb, p_hide_names boolean default true, p_mode text default 'classic', p_teams int default 0)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  qs jsonb;
  c text;
  rid uuid;
  b bytea;
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if coalesce(p_mode, 'classic') not in ('classic', 'team') or (p_mode = 'team' and coalesce(p_teams, 0) not between 2 and 4) then raise exception 'bad mode'; end if;
  qs := cortex_arena_clean_questions(p_questions);
  update cortex_arena_rooms set state = 'finished', finished_at = now() where class_id = p_class and state <> 'finished';
  loop
    b := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    c := lpad((((get_byte(b, 0) * 65536 + get_byte(b, 1) * 256 + get_byte(b, 2)) % 900000) + 100000)::text, 6, '0');
    exit when not exists (select 1 from cortex_arena_rooms where code = c and state <> 'finished');
  end loop;
  insert into cortex_arena_rooms (class_id, code, host, seconds, hide_names, mode, teams)
  values (p_class, c, auth.uid(), least(greatest(coalesce(p_seconds, 20), 10), 60), coalesce(p_hide_names, true),
    coalesce(p_mode, 'classic'), case when p_mode = 'team' then p_teams else 0 end)
  returning id into rid;
  insert into cortex_arena_questions (room_id, idx, card_id, kind, prompt, options, answer)
  select rid, (o - 1)::int, q->>'card_id', q->>'kind', q->>'prompt', q->'options', (q->>'answer')::int
  from jsonb_array_elements(qs) with ordinality as t(q, o);
  return jsonb_build_object('id', rid, 'code', c);
end;
$$;

-- The next question (from the lobby, or after a reveal); past the last one, the room finishes.
create or replace function public.arena_next(p_room uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  r cortex_arena_rooms := cortex_arena_room_teach(p_room);
  total int;
begin
  if r.state = 'finished' then return jsonb_build_object('state', 'finished'); end if;
  if r.state = 'question' then raise exception 'question still open'; end if;
  select count(*) into total from cortex_arena_questions where room_id = p_room;
  -- Starting a team game: anyone the teacher's split missed joins the smallest team
  if r.q_index = -1 and r.mode = 'team' then
    perform 1 from cortex_arena_players where room_id = p_room for update;
    declare u uuid;
    begin
      for u in select user_id from cortex_arena_players where room_id = p_room and team is null order by joined_at loop
        update cortex_arena_players set team = cortex_arena_smallest_team(p_room) where room_id = p_room and user_id = u;
      end loop;
    end;
  end if;
  if r.q_index + 1 >= total then
    update cortex_arena_rooms set state = 'finished', finished_at = now() where id = p_room;
    return jsonb_build_object('state', 'finished');
  end if;
  update cortex_arena_rooms set state = 'question', q_index = r.q_index + 1, q_opened_at = now() where id = p_room;
  return jsonb_build_object('state', 'question', 'q_index', r.q_index + 1);
end;
$$;

-- Close the open question: no more answers; whoever did not answer loses their run of right answers.
create or replace function public.arena_lock(p_room uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  r cortex_arena_rooms := cortex_arena_room_teach(p_room);
begin
  if r.state <> 'question' then return jsonb_build_object('state', r.state); end if;
  update cortex_arena_rooms set state = 'reveal' where id = p_room;
  update cortex_arena_players p set streak = 0
  where p.room_id = p_room and not exists (select 1 from cortex_arena_answers a where a.room_id = p_room and a.idx = r.q_index and a.user_id = p.user_id);
  return jsonb_build_object('state', 'reveal');
end;
$$;

create or replace function public.arena_finish(p_room uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  r cortex_arena_rooms := cortex_arena_room_teach(p_room);
begin
  update cortex_arena_rooms set state = 'finished', finished_at = coalesce(finished_at, now()) where id = r.id;
  return jsonb_build_object('state', 'finished');
end;
$$;

-- The teacher's split into teams (user id → team 1..N), before the first question.
create or replace function public.arena_teams_set(p_room uuid, p_teams jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  r cortex_arena_rooms := cortex_arena_room_teach(p_room);
begin
  if r.mode <> 'team' or r.state <> 'lobby' then raise exception 'bad mode'; end if;
  if jsonb_typeof(p_teams) <> 'object' then raise exception 'bad mode'; end if;
  update cortex_arena_players p set team = (t.value #>> '{}')::int
  from jsonb_each(p_teams) t
  where p.room_id = p_room and p.user_id::text = t.key
    and jsonb_typeof(t.value) = 'number' and (t.value #>> '{}') ~ '^[1-4]$' and (t.value #>> '{}')::int <= r.teams;
  return jsonb_build_object('ok', true);
end;
$$;

-- Everything the projector shows: the room, the players, the question (with
-- its answer only once locked), how many answered, and per option how many
-- chose it once locked; at the end, each question's share of right answers.
create or replace function public.arena_host_state(p_room uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  r cortex_arena_rooms := cortex_arena_room_teach(p_room);
  q cortex_arena_questions;
begin
  select * into q from cortex_arena_questions where room_id = p_room and idx = r.q_index;
  return jsonb_build_object(
    'id', r.id, 'class_id', r.class_id, 'code', r.code, 'mode', r.mode, 'teams', r.teams, 'seconds', r.seconds, 'hide_names', r.hide_names,
    'state', r.state, 'q_index', r.q_index, 'q_opened_at', r.q_opened_at, 'now', now(),
    'total', (select count(*) from cortex_arena_questions where room_id = p_room),
    'players', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('user_id', k.user_id, 'name', k.name, 'score', k.score, 'rank', k.rank,
      'team', (select team from cortex_arena_players x where x.room_id = p_room and x.user_id = k.user_id)))) from cortex_arena_ranking(p_room) k), '[]'::jsonb),
    'team_scores', case when r.mode = 'team' then coalesce((select jsonb_agg(jsonb_build_object('team', t.team, 'members', t.members, 'score', t.score, 'rank', t.rank)) from cortex_arena_teams(p_room) t), '[]'::jsonb) end,
    'question', case when q.room_id is not null and r.state in ('question', 'reveal') then jsonb_strip_nulls(jsonb_build_object(
      'idx', q.idx, 'card_id', q.card_id, 'kind', q.kind, 'prompt', q.prompt, 'options', q.options,
      'answer', case when r.state = 'reveal' then q.answer end,
      'answered', (select count(*) from cortex_arena_answers a where a.room_id = p_room and a.idx = q.idx),
      'counts', case when r.state = 'reveal' then (
        select jsonb_agg((select count(*) from cortex_arena_answers a where a.room_id = p_room and a.idx = q.idx and a.choice = i) order by i)
        from generate_series(0, jsonb_array_length(q.options) - 1) i
      ) end
    )) end,
    'summary', case when r.state = 'finished' then coalesce((
      select jsonb_agg(jsonb_build_object(
        'idx', x.idx, 'card_id', x.card_id, 'prompt', x.prompt, 'right', x.options->>x.answer,
        'answered', (select count(*) from cortex_arena_answers a where a.room_id = p_room and a.idx = x.idx),
        'correct', (select count(*) from cortex_arena_answers a where a.room_id = p_room and a.idx = x.idx and a.correct)
      ) order by x.idx)
      from cortex_arena_questions x where x.room_id = p_room
    ), '[]'::jsonb) end,
    -- Per student at the end: right answers, how fast, and quick wrong answers (under 1.5 s: likely a guess)
    'stats', case when r.state = 'finished' then coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id', p.user_id, 'name', p.name,
        'answered', (select count(*) from cortex_arena_answers a where a.room_id = p_room and a.user_id = p.user_id),
        'correct', (select count(*) from cortex_arena_answers a where a.room_id = p_room and a.user_id = p.user_id and a.correct),
        'avg_ms', (select round(avg(a.ms))::int from cortex_arena_answers a where a.room_id = p_room and a.user_id = p.user_id),
        'fast_wrong', (select count(*) from cortex_arena_answers a where a.room_id = p_room and a.user_id = p.user_id and not a.correct and a.ms < 1500)
      ) order by p.name)
      from cortex_arena_players p where p.room_id = p_room
    ), '[]'::jsonb) end
  );
end;
$$;

-- ── students ────────────────────────────────────────────────────────────

-- Rooms running now in this student's classes (Lexica shows "Vào đấu trường").
create or replace function public.arena_open_rooms()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'code', r.code, 'class', c.name, 'state', r.state) order by r.created_at desc), '[]'::jsonb)
  from cortex_arena_rooms r
  join cortex_classes c on c.id = r.class_id
  join cortex_class_members m on m.class_id = r.class_id and m.user_id = auth.uid()
  where r.state <> 'finished' and r.created_at > now() - interval '6 hours';
$$;

-- Join by code: only the class's students. Joining again (a reload, a lost connection) keeps the score.
create or replace function public.arena_join(p_code text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  r cortex_arena_rooms;
  nm text;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into r from cortex_arena_rooms where code = trim(p_code) and state <> 'finished' and created_at > now() - interval '6 hours';
  if r.id is null then raise exception 'no such room'; end if;
  select display_name into nm from cortex_class_members where class_id = r.class_id and user_id = auth.uid();
  if nm is null then raise exception 'not in this class'; end if;
  insert into cortex_arena_players (room_id, user_id, name) values (r.id, auth.uid(), nm)
  on conflict (room_id, user_id) do nothing;
  -- A team game already under way: a newcomer joins the smallest team
  if r.mode = 'team' and r.state <> 'lobby' then
    update cortex_arena_players set team = cortex_arena_smallest_team(r.id) where room_id = r.id and user_id = auth.uid() and team is null;
  end if;
  return jsonb_build_object('id', r.id);
end;
$$;

-- What a player's phone shows: the question without its answer while open;
-- once locked, the answer, their own result, score and rank; at the end,
-- their rank and the top 3.
create or replace function public.arena_state(p_room uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  r cortex_arena_rooms;
  q cortex_arena_questions;
  me cortex_arena_players;
  mine cortex_arena_answers;
  my_rank int;
begin
  select * into r from cortex_arena_rooms where id = p_room;
  select * into me from cortex_arena_players where room_id = p_room and user_id = auth.uid();
  if r.id is null or me.user_id is null then raise exception 'no such room'; end if;
  select * into q from cortex_arena_questions where room_id = p_room and idx = r.q_index;
  select * into mine from cortex_arena_answers where room_id = p_room and idx = r.q_index and user_id = auth.uid();
  select k.rank into my_rank from cortex_arena_ranking(p_room) k where k.user_id = auth.uid();
  return jsonb_strip_nulls(jsonb_build_object(
    'id', r.id, 'state', r.state, 'q_index', r.q_index, 'seconds', r.seconds, 'q_opened_at', r.q_opened_at, 'now', now(),
    'total', (select count(*) from cortex_arena_questions where room_id = p_room),
    'class', (select name from cortex_classes where id = r.class_id),
    'name', me.name, 'score', me.score, 'streak', me.streak, 'rank', my_rank,
    'mode', r.mode, 'team', me.team,
    'team_score', (select t.score from cortex_arena_teams(p_room) t where t.team = me.team),
    'team_rank', (select t.rank from cortex_arena_teams(p_room) t where t.team = me.team),
    'teams', nullif(r.teams, 0),
    'players', (select count(*) from cortex_arena_players where room_id = p_room),
    'question', case when q.room_id is not null and r.state in ('question', 'reveal') then jsonb_strip_nulls(jsonb_build_object(
      'idx', q.idx, 'kind', q.kind, 'prompt', q.prompt, 'options', q.options,
      'answer', case when r.state = 'reveal' then q.answer end
    )) end,
    'mine', case when mine.user_id is not null then jsonb_build_object(
      'choice', mine.choice,
      'correct', case when r.state <> 'question' then mine.correct end,
      'points', case when r.state <> 'question' then mine.points end
    ) end,
    'top', case when r.state = 'finished' then (select jsonb_agg(jsonb_build_object('name', k.name, 'score', k.score, 'rank', k.rank)) from (select * from cortex_arena_ranking(p_room) limit 3) k) end
  ));
end;
$$;

-- An answer to the open question: first one counts, timed by the server.
-- Says only that it was received; right or wrong shows when the teacher locks.
create or replace function public.arena_answer(p_room uuid, p_idx int, p_choice int)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  r cortex_arena_rooms;
  q cortex_arena_questions;
  me cortex_arena_players;
  ms int;
  ok boolean;
  pts int;
begin
  select * into r from cortex_arena_rooms where id = p_room for update;
  select * into me from cortex_arena_players where room_id = p_room and user_id = auth.uid() for update;
  if r.id is null or me.user_id is null then raise exception 'no such room'; end if;
  if r.state <> 'question' or r.q_index <> p_idx or now() > r.q_opened_at + make_interval(secs => r.seconds) + cortex_arena_grace() then
    raise exception 'too late';
  end if;
  select * into q from cortex_arena_questions where room_id = p_room and idx = p_idx;
  if p_choice is null or p_choice < 0 or p_choice >= jsonb_array_length(q.options) then raise exception 'bad answer'; end if;
  if exists (select 1 from cortex_arena_answers where room_id = p_room and idx = p_idx and user_id = auth.uid()) then
    return jsonb_build_object('received', true);
  end if;
  ms := least(greatest((extract(epoch from now() - r.q_opened_at) * 1000)::int, 0), r.seconds * 1000);
  ok := p_choice = q.answer;
  pts := cortex_arena_points(ok, ms, r.seconds, me.streak);
  insert into cortex_arena_answers (room_id, idx, user_id, choice, correct, ms, points) values (p_room, p_idx, auth.uid(), p_choice, ok, ms, pts);
  update cortex_arena_players set score = score + pts, streak = case when ok then streak + 1 else 0 end
  where room_id = p_room and user_id = auth.uid();
  return jsonb_build_object('received', true);
end;
$$;

-- A student's answers in rooms finished in the last 14 days, by the word asked:
-- Lexica puts the words they got wrong back into review, and counts a quick
-- right answer as remembering it. Lexica keeps which rooms it already applied.
create or replace function public.arena_my_results()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'room_id', r.id, 'seconds', r.seconds, 'finished_at', r.finished_at,
    'answers', (
      select coalesce(jsonb_agg(jsonb_build_object('card_id', q.card_id, 'correct', a.correct, 'ms', a.ms) order by q.idx), '[]'::jsonb)
      from cortex_arena_answers a join cortex_arena_questions q on q.room_id = a.room_id and q.idx = a.idx
      where a.room_id = r.id and a.user_id = auth.uid() and q.card_id is not null
    )
  ) order by r.finished_at), '[]'::jsonb)
  from cortex_arena_rooms r
  join cortex_arena_players p on p.room_id = r.id and p.user_id = auth.uid()
  where r.state = 'finished' and r.finished_at > now() - interval '14 days';
$$;

do $$
declare f text;
begin
  foreach f in array array['arena_open(uuid, int, jsonb, boolean, text, int)', 'arena_teams_set(uuid, jsonb)', 'arena_my_results()', 'arena_next(uuid)', 'arena_lock(uuid)', 'arena_finish(uuid)',
    'arena_host_state(uuid)', 'arena_open_rooms()', 'arena_join(text)', 'arena_state(uuid)', 'arena_answer(uuid, int, int)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['cortex_arena_grace()', 'cortex_arena_points(boolean, int, int, int)', 'cortex_arena_ranking(uuid)',
    'cortex_arena_clean_questions(jsonb)', 'cortex_arena_room_teach(uuid)', 'cortex_arena_teams(uuid)', 'cortex_arena_smallest_team(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- packages/classroom/sql/classroom_tests.sql
-- ============================================================

-- Class tests (docs/TEACH_PLAN.md, T3): the teacher gives a test of multiple
-- choice questions on the class's words; each student takes it in Lexica in
-- their own time, once, before the due date. Runs after classroom_arena.sql
-- (it checks questions the same way). Safe to re-run.
--
-- The server keeps the answers: a student sees a question's answer only after
-- handing the test in, and the score is counted here. The teacher sees each
-- student's score and the words they missed, to give a review per student.
-- Every read and write goes through the functions below; the tables have RLS
-- on and no policies.

create table if not exists cortex_class_tests (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references cortex_classes(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 120),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  due_on date,
  closed_at timestamptz
);
create index if not exists cortex_class_tests_class_idx on cortex_class_tests (class_id, created_at desc);

create table if not exists cortex_class_test_questions (
  test_id uuid not null references cortex_class_tests(id) on delete cascade,
  idx int not null,
  card_id text,
  kind text not null,
  prompt text not null,
  options jsonb not null,
  answer int not null,
  primary key (test_id, idx)
);

create table if not exists cortex_class_test_attempts (
  test_id uuid not null references cortex_class_tests(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  started_at timestamptz not null default now(),
  submitted_at timestamptz,
  correct int,
  primary key (test_id, user_id)
);

create table if not exists cortex_class_test_answers (
  test_id uuid not null references cortex_class_tests(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  idx int not null,
  choice int not null,
  at timestamptz not null default now(),
  primary key (test_id, user_id, idx)
);

alter table cortex_class_tests enable row level security;
alter table cortex_class_test_questions enable row level security;
alter table cortex_class_test_attempts enable row level security;
alter table cortex_class_test_answers enable row level security;

-- ── helpers ─────────────────────────────────────────────────────────────

create or replace function public.cortex_test_teach(p_test uuid)
returns cortex_class_tests language plpgsql stable security definer set search_path = public as $$
declare
  t cortex_class_tests;
begin
  select * into t from cortex_class_tests where id = p_test;
  if t.id is null then raise exception 'no such test'; end if;
  if not classroom_can_teach(t.class_id) then raise exception 'not the teacher'; end if;
  return t;
end;
$$;

-- The test, for one of its class's students.
create or replace function public.cortex_test_student(p_test uuid)
returns cortex_class_tests language plpgsql stable security definer set search_path = public as $$
declare
  t cortex_class_tests;
begin
  select * into t from cortex_class_tests where id = p_test;
  if t.id is null or not exists (select 1 from cortex_class_members where class_id = t.class_id and user_id = auth.uid()) then
    raise exception 'no such test';
  end if;
  return t;
end;
$$;

-- ── teacher ─────────────────────────────────────────────────────────────

create or replace function public.test_create(p_class uuid, p_title text, p_due date, p_questions jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  qs jsonb;
  tid uuid;
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  qs := cortex_arena_clean_questions(p_questions);
  insert into cortex_class_tests (class_id, title, created_by, due_on)
  values (p_class, left(coalesce(nullif(trim(p_title), ''), 'Bài kiểm tra'), 120), auth.uid(), p_due)
  returning id into tid;
  insert into cortex_class_test_questions (test_id, idx, card_id, kind, prompt, options, answer)
  select tid, (o - 1)::int, q->>'card_id', q->>'kind', q->>'prompt', q->'options', (q->>'answer')::int
  from jsonb_array_elements(qs) with ordinality as t(q, o);
  return jsonb_build_object('id', tid);
end;
$$;

-- Close a test (no more answers) or open it again.
create or replace function public.test_close(p_test uuid, p_closed boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  t cortex_class_tests := cortex_test_teach(p_test);
begin
  update cortex_class_tests set closed_at = case when coalesce(p_closed, true) then coalesce(closed_at, now()) end where id = t.id;
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.test_delete(p_test uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  t cortex_class_tests := cortex_test_teach(p_test);
begin
  delete from cortex_class_tests where id = t.id;
  return jsonb_build_object('ok', true);
end;
$$;

-- The class's tests, newest first, with how many handed in and the average score.
create or replace function public.tests_list(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not the teacher'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', t.id, 'title', t.title, 'created_at', t.created_at, 'due_on', t.due_on, 'closed', t.closed_at is not null,
      'total', (select count(*) from cortex_class_test_questions q where q.test_id = t.id),
      'submitted', (select count(*) from cortex_class_test_attempts a where a.test_id = t.id and a.submitted_at is not null),
      'average', (select round(avg(a.correct)::numeric, 1) from cortex_class_test_attempts a where a.test_id = t.id and a.submitted_at is not null)
    ) order by t.created_at desc)
    from cortex_class_tests t where t.class_id = p_class
  ), '[]'::jsonb);
end;
$$;

-- A test's results: each student of the class (handed in, started, or not
-- yet), their score and the words they missed; each question's share right.
create or replace function public.test_results(p_test uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  t cortex_class_tests := cortex_test_teach(p_test);
begin
  return jsonb_build_object(
    'id', t.id, 'title', t.title, 'created_at', t.created_at, 'due_on', t.due_on, 'closed', t.closed_at is not null,
    'total', (select count(*) from cortex_class_test_questions q where q.test_id = t.id),
    'students', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'user_id', m.user_id, 'name', m.display_name,
        'status', case when a.submitted_at is not null then 'submitted' when a.user_id is not null then 'started' else 'not_started' end,
        'correct', a.correct, 'submitted_at', a.submitted_at,
        'missed', case when a.submitted_at is not null then (
          select coalesce(jsonb_agg(q.card_id order by q.idx), '[]'::jsonb) from cortex_class_test_questions q
          where q.test_id = t.id and q.card_id is not null
            and not exists (select 1 from cortex_class_test_answers x where x.test_id = t.id and x.user_id = m.user_id and x.idx = q.idx and x.choice = q.answer)
        ) end
      )) order by m.display_name)
      from cortex_class_members m
      left join cortex_class_test_attempts a on a.test_id = t.id and a.user_id = m.user_id
      where m.class_id = t.class_id
    ), '[]'::jsonb),
    'questions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'idx', q.idx, 'card_id', q.card_id, 'prompt', q.prompt, 'right', q.options->>q.answer,
        'answered', (select count(*) from cortex_class_test_answers x join cortex_class_test_attempts a on a.test_id = x.test_id and a.user_id = x.user_id and a.submitted_at is not null where x.test_id = t.id and x.idx = q.idx),
        'correct', (select count(*) from cortex_class_test_answers x join cortex_class_test_attempts a on a.test_id = x.test_id and a.user_id = x.user_id and a.submitted_at is not null where x.test_id = t.id and x.idx = q.idx and x.choice = q.answer)
      ) order by q.idx)
      from cortex_class_test_questions q where q.test_id = t.id
    ), '[]'::jsonb)
  );
end;
$$;

-- ── students ────────────────────────────────────────────────────────────

-- This student's tests from the last 60 days, in every class: still to do first.
create or replace function public.my_tests()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'id', t.id, 'class_id', t.class_id, 'class', c.name, 'title', t.title, 'due_on', t.due_on, 'closed', t.closed_at is not null,
    'total', (select count(*) from cortex_class_test_questions q where q.test_id = t.id),
    'status', case when a.submitted_at is not null then 'submitted' when a.user_id is not null then 'started' else 'not_started' end,
    'correct', a.correct
  )) order by (a.submitted_at is not null), t.created_at desc), '[]'::jsonb)
  from cortex_class_tests t
  join cortex_classes c on c.id = t.class_id
  join cortex_class_members m on m.class_id = t.class_id and m.user_id = auth.uid()
  left join cortex_class_test_attempts a on a.test_id = t.id and a.user_id = auth.uid()
  where t.created_at > now() - interval '60 days';
$$;

-- Open a test: its questions, without answers until handed in (or the test
-- is closed); this student's answers so far. Opening an open test starts the attempt.
create or replace function public.test_take(p_test uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  t cortex_class_tests := cortex_test_student(p_test);
  a cortex_class_test_attempts;
begin
  if t.closed_at is null then
    insert into cortex_class_test_attempts (test_id, user_id) values (t.id, auth.uid()) on conflict do nothing;
  end if;
  select * into a from cortex_class_test_attempts where test_id = t.id and user_id = auth.uid();
  return jsonb_build_object(
    'id', t.id, 'title', t.title, 'due_on', t.due_on, 'closed', t.closed_at is not null,
    'class', (select name from cortex_classes where id = t.class_id),
    'submitted', a.submitted_at is not null, 'correct', a.correct,
    'questions', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'idx', q.idx, 'card_id', q.card_id, 'kind', q.kind, 'prompt', q.prompt, 'options', q.options,
        'answer', case when a.submitted_at is not null or t.closed_at is not null then q.answer end,
        'choice', (select x.choice from cortex_class_test_answers x where x.test_id = t.id and x.user_id = auth.uid() and x.idx = q.idx)
      )) order by q.idx)
      from cortex_class_test_questions q where q.test_id = t.id
    ), '[]'::jsonb)
  );
end;
$$;

-- Answer (or change an answer) before handing in.
create or replace function public.test_answer(p_test uuid, p_idx int, p_choice int)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  t cortex_class_tests := cortex_test_student(p_test);
  n int;
begin
  if t.closed_at is not null then raise exception 'test closed'; end if;
  if exists (select 1 from cortex_class_test_attempts where test_id = t.id and user_id = auth.uid() and submitted_at is not null) then raise exception 'already handed in'; end if;
  select jsonb_array_length(options) into n from cortex_class_test_questions where test_id = t.id and idx = p_idx;
  if n is null or p_choice is null or p_choice < 0 or p_choice >= n then raise exception 'bad answer'; end if;
  insert into cortex_class_test_attempts (test_id, user_id) values (t.id, auth.uid()) on conflict do nothing;
  insert into cortex_class_test_answers (test_id, user_id, idx, choice) values (t.id, auth.uid(), p_idx, p_choice)
  on conflict (test_id, user_id, idx) do update set choice = excluded.choice, at = now();
  return jsonb_build_object('ok', true);
end;
$$;

-- Hand in: the score is counted here (a question left blank is wrong), once.
create or replace function public.test_submit(p_test uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  t cortex_class_tests := cortex_test_student(p_test);
  c int;
begin
  if t.closed_at is not null then raise exception 'test closed'; end if;
  if exists (select 1 from cortex_class_test_attempts where test_id = t.id and user_id = auth.uid() and submitted_at is not null) then raise exception 'already handed in'; end if;
  select count(*) into c from cortex_class_test_answers x join cortex_class_test_questions q on q.test_id = x.test_id and q.idx = x.idx
  where x.test_id = t.id and x.user_id = auth.uid() and x.choice = q.answer;
  insert into cortex_class_test_attempts (test_id, user_id, submitted_at, correct) values (t.id, auth.uid(), now(), c)
  on conflict (test_id, user_id) do update set submitted_at = now(), correct = c;
  return test_take(p_test);
end;
$$;

do $$
declare f text;
begin
  foreach f in array array['test_create(uuid, text, date, jsonb)', 'test_close(uuid, boolean)', 'test_delete(uuid)', 'tests_list(uuid)',
    'test_results(uuid)', 'my_tests()', 'test_take(uuid)', 'test_answer(uuid, int, int)', 'test_submit(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['cortex_test_teach(uuid)', 'cortex_test_student(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- packages/classroom-lexica/sql/classroom_lexica.sql
-- ============================================================

-- Classroom module: Lexica (docs/CLASSROOM.md). What a Lexica lesson is,
-- what a Lexica student reports, and how the class ranks them. Runs after
-- packages/classroom/sql/classroom_core.sql. Safe to re-run.
--
-- Assignment kinds:
--   words  {card_ids: text[], missing_words: text[], mode: 'only'|'mixed'}
-- Metrics (per class):
--   {counts: {hieu,nho,gap,dung,doi,known}, assigned: {hieu,nho,gap,dung,total}, words: {cardId: 1..5}}
-- Settings: {branch: 'cert'|'talk', level: 'beginner'|'intermediate'|'advanced'|'expert'|null,
--            ends_on: 'YYYY-MM-DD'|null, target_score: 400..1800|null}  (the last two feed the forecasts)
-- Metrics also carry review: {overdue, due7, recall14: [right, total], atRisk: [cardId]} (W4 forecasts)

insert into cortex_apps (id, name) values ('lexica', 'Lexica') on conflict (id) do update set name = excluded.name;

-- Words a teacher assigned that Lexica has no card for yet; Studio writes them.
create table if not exists lexica_word_requests (
  id uuid primary key default gen_random_uuid(),
  class_id uuid references cortex_classes(id) on delete set null,
  word text not null check (char_length(word) between 1 and 60),
  status text not null default 'open' check (status in ('open','done')),
  created_at timestamptz not null default now()
);
create index if not exists lexica_word_requests_status_idx on lexica_word_requests (status, created_at);
alter table lexica_word_requests enable row level security;
do $$ begin
  -- Studio editors read and close word requests (is_studio_editor from migration_studio.sql).
  if to_regprocedure('public.is_studio_editor()') is not null then
    drop policy if exists "lexica_word_requests editors" on lexica_word_requests;
    create policy "lexica_word_requests editors" on lexica_word_requests
      for all using (is_studio_editor()) with check (is_studio_editor());
  end if;
end $$;

-- Step counts: four non-negative ints, plus "Đời", a total and words known beforehand ("known") when given.
create or replace function public.lexica_counts(p jsonb)
returns jsonb language sql immutable as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'hieu', least(greatest(coalesce((p->>'hieu')::int, 0), 0), 100000),
    'nho', least(greatest(coalesce((p->>'nho')::int, 0), 0), 100000),
    'gap', least(greatest(coalesce((p->>'gap')::int, 0), 0), 100000),
    'dung', least(greatest(coalesce((p->>'dung')::int, 0), 0), 100000),
    'doi', case when p ? 'doi' then least(greatest((p->>'doi')::int, 0), 100000) end,
    'total', case when p ? 'total' then least(greatest((p->>'total')::int, 0), 100000) end,
    'known', case when p ? 'known' then least(greatest((p->>'known')::int, 0), 100000) end
  ));
$$;

-- ── hooks ───────────────────────────────────────────────────────────────

create or replace function public.classroom_lexica_clean_settings(p jsonb)
returns jsonb language sql immutable as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'branch', case when p->>'branch' = 'talk' then 'talk' else 'cert' end,
    'level', case when p->>'level' in ('beginner','intermediate','advanced','expert') then p->>'level' end,
    -- The course's last day and the class's target score, for the forecasts (forecast.ts)
    'ends_on', case when p->>'ends_on' ~ '^\d{4}-\d{2}-\d{2}$' and (p->>'ends_on') between '2020-01-01' and '2100-12-31' then p->>'ends_on' end,
    'target_score', case when jsonb_typeof(p->'target_score') = 'number' and (p->>'target_score')::numeric between 400 and 1800
      then round((p->>'target_score')::numeric)::int end
  ));
$$;

create or replace function public.classroom_lexica_clean_payload(p_kind text, p jsonb)
returns jsonb language plpgsql immutable as $$
declare
  ids jsonb;
  missing jsonb;
begin
  if p_kind <> 'words' then raise exception 'bad payload'; end if;
  select coalesce(jsonb_agg(distinct x), '[]') into ids
  from (select jsonb_array_elements_text(coalesce(p->'card_ids', '[]')) x limit 200) t where char_length(x) between 1 and 40;
  select coalesce(jsonb_agg(distinct lower(trim(x))), '[]') into missing
  from (select jsonb_array_elements_text(coalesce(p->'missing_words', '[]')) x limit 200) t where char_length(trim(x)) between 1 and 60;
  if jsonb_array_length(ids) = 0 and jsonb_array_length(missing) = 0 then raise exception 'no words'; end if;
  return jsonb_build_object('card_ids', ids, 'missing_words', missing, 'mode', case when p->>'mode' = 'mixed' then 'mixed' else 'only' end);
end;
$$;

-- What a class may see: the student's counts, their counts on this class's words, and steps on those words only.
create or replace function public.classroom_lexica_clean_metrics(p_class uuid, p jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  words jsonb;
  sounds jsonb;
  review jsonb;
  r jsonb := case when jsonb_typeof(p->'review') = 'object' then p->'review' end;
  total int;
begin
  -- Words of this class's lessons: the whole class's, and the ones given to this student alone
  select coalesce(jsonb_object_agg(k, least(greatest((v #>> '{}')::int, 0), 5)), '{}') into words
  from jsonb_each(coalesce(p->'words', '{}')) e(k, v)
  where jsonb_typeof(v) = 'number'
    and exists (
      select 1 from cortex_class_assignments a
      where a.class_id = p_class and a.app = 'lexica' and a.payload->'card_ids' ? k
        and (a.for_user is null or a.for_user = auth.uid())
    );
  -- Review numbers (docs/TEACH_PLAN.md 2.1): counts 0-100000, right <= total, and only
  -- this class's lesson words among the ones at risk.
  if r is not null then
    total := case when jsonb_typeof(r->'recall14') = 'array' and jsonb_typeof(r->'recall14'->1) = 'number'
      then least(greatest(round((r->'recall14'->>1)::numeric), 0), 100000)::int else 0 end;
    review := jsonb_build_object(
      'overdue', case when jsonb_typeof(r->'overdue') = 'number' then least(greatest(round((r->>'overdue')::numeric), 0), 100000)::int else 0 end,
      'due7', case when jsonb_typeof(r->'due7') = 'number' then least(greatest(round((r->>'due7')::numeric), 0), 100000)::int else 0 end,
      'recall14', jsonb_build_array(
        case when jsonb_typeof(r->'recall14'->0) = 'number' then least(greatest(round((r->'recall14'->>0)::numeric), 0), total)::int else 0 end,
        total),
      'atRisk', coalesce((
        select jsonb_agg(x) from (
          select distinct x from jsonb_array_elements_text(case when jsonb_typeof(r->'atRisk') = 'array' then r->'atRisk' else '[]' end) x
          where char_length(x) between 1 and 40
            and exists (
              select 1 from cortex_class_assignments a
              where a.class_id = p_class and a.app = 'lexica' and a.payload->'card_ids' ? x
                and (a.for_user is null or a.for_user = auth.uid())
            )
          limit 200
        ) t
      ), '[]')
    );
  end if;
  -- Pronunciation (docs/LEXICA_PRONUNCIATION_DESIGN.md, 7.3): per sound group,
  -- [tries, misses] over 14 days. Numbers only: known groups, 0-10000, misses <= tries.
  select coalesce(jsonb_object_agg(k, jsonb_build_array(t, least(m, t))), '{}') into sounds
  from (
    select k,
      least(greatest(round((v->>0)::numeric), 0), 10000)::int as t,
      least(greatest(round((v->>1)::numeric), 0), 10000)::int as m
    from jsonb_each(case when jsonb_typeof(p->'sounds') = 'object' then p->'sounds' else '{}' end) e(k, v)
    where k in ('final_consonant', 'final_voicing', 'th', 'cluster', 'ending', 'long_short', 'ch_j', 'final_ng', 'final_l', 'initial_z', 'ae_e')
      and jsonb_typeof(v) = 'array' and jsonb_array_length(v) = 2
      and jsonb_typeof(v->0) = 'number' and jsonb_typeof(v->1) = 'number'
  ) x;
  return jsonb_build_object(
    'counts', lexica_counts(coalesce(p->'counts', '{}')),
    'assigned', lexica_counts(coalesce(p->'assigned'->(p_class::text), '{}')),
    'words', words,
    'sounds', sounds
  ) || case when review is not null then jsonb_build_object('review', review) else '{}'::jsonb end;
end;
$$;

-- Ranked by words they can say (Dùng), then remember (Nhớ); never by game points.
create or replace function public.classroom_lexica_rank(p jsonb)
returns numeric language sql immutable as $$
  select coalesce((p->'counts'->>'dung')::numeric, 0) * 100000 + coalesce((p->'counts'->>'nho')::numeric, 0);
$$;

create or replace function public.classroom_lexica_after_assign(p_class uuid, p_assignment uuid, p jsonb)
returns void language sql volatile security definer set search_path = public as $$
  insert into lexica_word_requests (class_id, word)
  select p_class, w from jsonb_array_elements_text(coalesce(p->'missing_words', '[]')) w;
$$;

do $$
declare f text;
begin
  foreach f in array array['classroom_lexica_clean_settings(jsonb)', 'classroom_lexica_clean_payload(text, jsonb)',
    'classroom_lexica_clean_metrics(uuid, jsonb)', 'classroom_lexica_rank(jsonb)', 'classroom_lexica_after_assign(uuid, uuid, jsonb)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- apps/lexica/supabase/migration_placement.sql
-- ============================================================

-- Verified vocabulary scores (docs/LEXICA_LEVEL_TEST_DESIGN.md, PR C).
--
-- The same adaptive test as app/lib/placement/engine.ts, run by the
-- database: it picks each question, keeps the right answer to itself,
-- times every answer and scores the test. A finished test gets a short
-- public code: /score/<code> shows it to anyone.
--
-- Run this file, then supabase/placement_bank.sql (the question bank,
-- generated from the deck). Idempotent.

create table if not exists public.lexica_placement_bank (
  card_id text primary key,
  word text not null,
  meaning text not null,
  elo int not null,
  level text not null,
  -- a collocation with the word blanked as ___, when the card has one
  phrase text,
  -- the stored voice clip of the word (single words only)
  audio text
);

create table if not exists public.lexica_placement_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  sound boolean not null default false,
  start_score int not null default 1000,
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  score int,
  sd int,
  level text,
  code text unique
);
create index if not exists lexica_placement_sessions_user_idx on public.lexica_placement_sessions (user_id, started_at desc);

create table if not exists public.lexica_placement_items (
  session_id uuid not null references public.lexica_placement_sessions(id) on delete cascade,
  n int not null,
  kind text not null check (kind in ('meaning', 'phrase', 'real', 'listen')),
  card_id text,
  prompt text not null,
  options jsonb not null,
  answer int not null,
  difficulty int,
  guess real not null,
  asked_at timestamptz not null default now(),
  answered_at timestamptz,
  response text check (response in ('right', 'wrong', 'skip')),
  primary key (session_id, n)
);

alter table public.lexica_placement_bank enable row level security;
alter table public.lexica_placement_sessions enable row level security;
alter table public.lexica_placement_items enable row level security;

-- ---------------------------------------------------------------- scoring

-- Mean and spread of the level from a session's answers: a Rasch model with
-- a guessing floor, on a grid, prior around the start score (as engine.ts).
create or replace function public.lexica_pl_estimate(p_session uuid, out score int, out sd int)
language plpgsql stable security definer set search_path = public as $$
declare
  start_score int;
  diffs int[];
  guesses real[];
  answers text[];
  a int;
  i int;
  p float8;
  ll float8;
  lls float8[] := '{}';
  grid int[] := '{}';
  top float8;
  w float8;
  total float8 := 0;
  mean float8 := 0;
  sq float8 := 0;
begin
  select s.start_score into start_score from lexica_placement_sessions s where s.id = p_session;
  select coalesce(array_agg(difficulty order by n), '{}'), coalesce(array_agg(guess order by n), '{}'), coalesce(array_agg(response order by n), '{}')
    into diffs, guesses, answers
    from lexica_placement_items where session_id = p_session and difficulty is not null and response is not null;
  a := 650;
  while a <= 1650 loop
    ll := -((a - start_score)::float8 ^ 2) / (2 * 400.0 ^ 2);
    for i in 1 .. coalesce(array_length(diffs, 1), 0) loop
      p := 1 / (1 + 10 ^ ((diffs[i] - a) / 400.0));
      ll := ll + ln(greatest(1e-9, case answers[i]
        when 'skip' then 1 - p
        when 'right' then guesses[i] + (1 - guesses[i]) * p
        else (1 - guesses[i]) * (1 - p) end));
    end loop;
    grid := grid || a;
    lls := lls || ll;
    a := a + 5;
  end loop;
  select max(x) into top from unnest(lls) x;
  for i in 1 .. array_length(grid, 1) loop
    w := exp(lls[i] - top);
    total := total + w;
    mean := mean + w * grid[i];
    sq := sq + w * grid[i] * grid[i];
  end loop;
  mean := mean / total;
  score := round(mean);
  sd := round(sqrt(greatest(0, sq / total - mean * mean)));
end;
$$;

-- What the learner sees of an item: never the answer, never the spoken word.
create or replace function public.lexica_pl_view(it lexica_placement_items)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'n', it.n,
    'kind', it.kind,
    'prompt', case when it.kind = 'listen' then null else it.prompt end,
    'audio', case when it.kind = 'listen' then (select audio from lexica_placement_bank where card_id = it.card_id) else null end,
    'options', it.options,
    'seconds', 20
  );
$$;

-- Picks and stores the next question near the current estimate.
create or replace function public.lexica_pl_next(p_session uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  s lexica_placement_sessions;
  n int;
  kinds text[];
  kind text;
  target int;
  fakes text[] := array['flendid','proctave','mivorous','scrandle','bluthery','tremulate','ganderly','plosiveness','cromptious','vintory',
    'sulberate','drimble','ostrify','quandish','perlocate','frostive','menticule','abrontic','glimper','reboundful',
    'carvulous','snerdish','implacent','wobbish','dextrify','trelling','obvolent','farcile','harbinate','clemptory'];
  fake text;
  c lexica_placement_bank;
  right_option text;
  wrong text[];
  opts text[];
  it lexica_placement_items;
begin
  select * into s from lexica_placement_sessions where id = p_session;
  select count(*) into n from lexica_placement_items where session_id = p_session;
  kinds := case when s.sound then array['meaning','listen','phrase','real','meaning','listen'] else array['meaning','phrase','meaning','real'] end;
  kind := kinds[(n % array_length(kinds, 1)) + 1];
  target := (lexica_pl_estimate(p_session)).score;

  if kind = 'real' and random() < 1.0 / 3 then
    select f into fake from unnest(fakes) f
      where f not in (select prompt from lexica_placement_items where session_id = p_session and card_id is null)
      order by random() limit 1;
    if fake is not null then
      insert into lexica_placement_items (session_id, n, kind, card_id, prompt, options, answer, difficulty, guess)
        values (p_session, n + 1, 'real', null, fake, '["Có, là từ tiếng Anh","Không, từ bịa"]', 1, null, 0.5)
        returning * into it;
      return lexica_pl_view(it);
    end if;
  end if;

  -- One of the four unasked cards nearest the estimate that suit the kind.
  select * into c from (
    select * from lexica_placement_bank b
     where b.card_id not in (select coalesce(card_id, '') from lexica_placement_items where session_id = p_session)
       and (kind <> 'phrase' or b.phrase is not null)
       and (kind <> 'listen' or b.audio is not null)
     order by abs(b.elo - target) limit 4
  ) near order by random() limit 1;
  if c.card_id is null then
    kind := 'meaning';
    select * into c from lexica_placement_bank b
     where b.card_id not in (select coalesce(card_id, '') from lexica_placement_items where session_id = p_session)
     order by abs(b.elo - target) limit 1;
  end if;

  if kind = 'real' then
    insert into lexica_placement_items (session_id, n, kind, card_id, prompt, options, answer, difficulty, guess)
      values (p_session, n + 1, 'real', c.card_id, c.word, '["Có, là từ tiếng Anh","Không, từ bịa"]', 0, c.elo - 100, 0.5)
      returning * into it;
    return lexica_pl_view(it);
  end if;

  -- Three wrong options from cards near the same difficulty: meanings (also for "listen": hear the
  -- word, pick its meaning, which needs the word and not only its spelling), or words (phrase).
  if kind in ('meaning', 'listen') then
    right_option := c.meaning;
    -- 3 of the 24 nearest (limit inside: `array_agg(...) ... limit 3` cut one row, not the options)
    select array_agg(v) into wrong from (
      select v from (
        select v from (
          select distinct on (lower(b.meaning)) b.meaning as v, abs(b.elo - c.elo) as d
            from lexica_placement_bank b
           where b.card_id <> c.card_id and lower(b.meaning) <> lower(c.meaning)
             and (position(' ' in b.word) > 0) = (position(' ' in c.word) > 0)
           order by lower(b.meaning), abs(b.elo - c.elo)
        ) x order by d limit 24
      ) y order by random() limit 3
    ) z;
  else
    right_option := c.word;
    select array_agg(v) into wrong from (
      select v from (
        select v from (
          select distinct on (b.word) b.word as v, abs(b.elo - c.elo) as d
            from lexica_placement_bank b
           where b.card_id <> c.card_id and b.word <> c.word
             and (position(' ' in b.word) > 0) = (position(' ' in c.word) > 0)
           order by b.word, abs(b.elo - c.elo)
        ) x order by d limit 24
      ) y order by random() limit 3
    ) z;
  end if;
  select array_agg(o order by random()) into opts from unnest(array[right_option] || wrong) o;

  insert into lexica_placement_items (session_id, n, kind, card_id, prompt, options, answer, difficulty, guess)
    values (p_session, n + 1, kind, c.card_id,
            case kind when 'phrase' then c.phrase else c.word end,
            to_jsonb(opts), array_position(opts, right_option) - 1,
            case kind when 'meaning' then c.elo else c.elo + 50 end, 0.25)
    returning * into it;
  return lexica_pl_view(it);
end;
$$;

-- ---------------------------------------------------------------- the API

-- Starts a verified test. A new score counts 14 days after the last one;
-- at most 5 starts a day, so a bad run cannot be restarted until lucky.
create or replace function public.lexica_placement_start(p_sound boolean default false)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  last_done lexica_placement_sessions;
  sid uuid;
begin
  if uid is null then raise exception 'not signed in'; end if;
  select * into last_done from lexica_placement_sessions
   where user_id = uid and score is not null order by finished_at desc limit 1;
  if last_done.id is not null and last_done.finished_at > now() - interval '14 days' then
    raise exception 'too soon: %', ceil(extract(epoch from (last_done.finished_at + interval '14 days' - now())) / 86400);
  end if;
  if (select count(*) from lexica_placement_sessions where user_id = uid and started_at > now() - interval '1 day') >= 5 then
    raise exception 'too many tries';
  end if;
  -- An unfinished test is given up.
  update lexica_placement_sessions set finished_at = now() where user_id = uid and finished_at is null;
  insert into lexica_placement_sessions (user_id, sound, start_score)
    values (uid, coalesce(p_sound, false), coalesce(last_done.score, 1000))
    returning id into sid;
  return jsonb_build_object('session', sid, 'item', lexica_pl_next(sid));
end;
$$;

-- Answers the open question (p_choice = option index, null = "không biết").
-- Late answers (over 25 seconds) count as "không biết". Returns the right
-- option of this question, then the next question or the result.
create or replace function public.lexica_placement_answer(p_session uuid, p_choice int)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  s lexica_placement_sessions;
  it lexica_placement_items;
  resp text;
  scored int;
  total int;
  est record;
  lvl text;
  the_code text;
  by_kind jsonb;
  fakes jsonb;
begin
  select * into s from lexica_placement_sessions where id = p_session and user_id = uid and finished_at is null;
  if s.id is null then raise exception 'no open test'; end if;
  select * into it from lexica_placement_items where session_id = p_session and response is null order by n desc limit 1;
  if it.n is null then raise exception 'no open question'; end if;

  resp := case
    when p_choice is null or now() - it.asked_at > interval '25 seconds' then 'skip'
    when p_choice = it.answer then 'right'
    else 'wrong' end;
  update lexica_placement_items set response = resp, answered_at = now() where session_id = p_session and n = it.n;

  select count(*) filter (where difficulty is not null), count(*) into scored, total
    from lexica_placement_items where session_id = p_session and response is not null;
  select * into est from lexica_pl_estimate(p_session);

  if not (scored >= 30 or total >= 45 or (scored >= 15 and est.sd <= 80)) then
    return jsonb_build_object('done', false, 'answer', it.answer, 'response', resp, 'item', lexica_pl_next(p_session));
  end if;

  est.score := least(1500, greatest(800, est.score));
  lvl := case when est.score < 950 then 'beginner' when est.score < 1150 then 'intermediate' when est.score < 1350 then 'advanced' else 'expert' end;
  loop
    the_code := substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);
    exit when length(the_code) = 8 and not exists (select 1 from lexica_placement_sessions where code = the_code);
  end loop;
  update lexica_placement_sessions
     set finished_at = now(), score = est.score, sd = est.sd, level = lvl, code = the_code
   where id = p_session;

  select coalesce(jsonb_object_agg(kind, jsonb_build_object('right', r, 'total', t)), '{}') into by_kind from (
    select kind, count(*) filter (where response = 'right') as r, count(*) as t
      from lexica_placement_items where session_id = p_session and card_id is not null group by kind
  ) k;
  select jsonb_build_object('yes', count(*) filter (where response = 'wrong'), 'total', count(*)) into fakes
    from lexica_placement_items where session_id = p_session and card_id is null;

  return jsonb_build_object('done', true, 'answer', it.answer, 'response', resp,
    'result', jsonb_build_object('score', est.score, 'sd', est.sd, 'level', lvl, 'code', the_code,
      'byKind', by_kind, 'fakes', fakes, 'questions', total, 'at', now()));
end;
$$;

-- A verified score by its public code, for /score/<code>. Only the score: no name, no answers.
create or replace function public.lexica_score_public(p_code text)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('score', score, 'sd', sd, 'level', level, 'at', finished_at, 'sound', sound)
    from lexica_placement_sessions where code = p_code and score is not null;
$$;

-- The signed-in learner's verified scores, oldest first.
create or replace function public.lexica_my_scores()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('score', score, 'sd', sd, 'level', level, 'at', finished_at, 'code', code) order by finished_at), '[]')
    from lexica_placement_sessions where user_id = auth.uid() and score is not null;
$$;

-- For a class's teacher (teach app): each student's last verified score and
-- the one before, read from the server's own tests, not from what the app
-- reports. Needs packages/classroom/sql/classroom_core.sql.
create or replace function public.lexica_class_scores(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not your class'; end if;
  return coalesce((
    select jsonb_object_agg(m.user_id, jsonb_build_object('score', t.score, 'sd', t.sd, 'level', t.level, 'at', t.finished_at, 'code', t.code, 'previous', t.previous))
      from cortex_class_members m
      join lateral (
        select s.score, s.sd, s.level, s.finished_at, s.code,
               lead(s.score) over (order by s.finished_at desc) as previous
          from lexica_placement_sessions s
         where s.user_id = m.user_id and s.score is not null
         order by s.finished_at desc limit 1
      ) t on true
     where m.class_id = p_class
  ), '{}'::jsonb);
end;
$$;

-- A class's verified scores over time, for the end-of-course forecast in Teach
-- (packages/classroom-lexica/forecast.ts): per student the last 10 tests of 180 days.
create or replace function public.lexica_class_score_history(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not classroom_can_teach(p_class) then raise exception 'not your class'; end if;
  return coalesce((
    select jsonb_object_agg(m.user_id, t.tests)
      from cortex_class_members m
      join lateral (
        select jsonb_agg(jsonb_build_object('score', x.score, 'sd', x.sd, 'at', x.finished_at) order by x.finished_at) as tests
          from (
            select s.score, s.sd, s.finished_at from lexica_placement_sessions s
             where s.user_id = m.user_id and s.score is not null and s.finished_at > now() - interval '180 days'
             order by s.finished_at desc limit 10
          ) x
      ) t on t.tests is not null
     where m.class_id = p_class
  ), '{}'::jsonb);
end;
$$;

revoke all on function public.lexica_pl_estimate(uuid) from public, anon, authenticated;
revoke all on function public.lexica_pl_view(lexica_placement_items) from public, anon, authenticated;
revoke all on function public.lexica_pl_next(uuid) from public, anon, authenticated;
revoke all on function public.lexica_placement_start(boolean) from public, anon;
revoke all on function public.lexica_placement_answer(uuid, int) from public, anon;
revoke all on function public.lexica_my_scores() from public, anon;
revoke all on function public.lexica_class_scores(uuid) from public, anon;
grant execute on function public.lexica_placement_start(boolean) to authenticated;
grant execute on function public.lexica_placement_answer(uuid, int) to authenticated;
grant execute on function public.lexica_my_scores() to authenticated;
grant execute on function public.lexica_class_scores(uuid) to authenticated;
revoke all on function public.lexica_class_score_history(uuid) from public, anon;
grant execute on function public.lexica_class_score_history(uuid) to authenticated;
grant execute on function public.lexica_score_public(text) to anon, authenticated;


-- ============================================================
-- packages/classroom-oratio/sql/classroom_oratio.sql
-- ============================================================

-- Classroom module: Oratio (docs/CLASSROOM.md). What an Oratio lesson is,
-- what an Oratio student reports, and how the class ranks them. Runs after
-- packages/classroom/sql/classroom_core.sql and Oratio's schema
-- (ielts_questions). Safe to re-run.
--
-- Assignment kinds:
--   topic      {category: text, part: 1|2|3|null, sessions: 1..20}
--   questions  {question_ids: uuid[]}
--   goal       {sessions: 0..50, minutes: 0..1000}   (at least one above 0)
-- Metrics (per class):
--   {sessions, minutes, ratings, band: {fluency,vocabulary,grammar,pronunciation,overall}|null,
--    current_band, target_band, progress: {assignmentId: {sessions, minutes, asked}}}
-- Settings: {target_band: 4..9 in steps of 0.5 | null}

insert into cortex_apps (id, name) values ('oratio', 'Oratio') on conflict (id) do update set name = excluded.name;

-- A band 1..9 in steps of 0.5, or null.
create or replace function public.oratio_band(v jsonb)
returns numeric language sql immutable as $$
  select case when jsonb_typeof(v) = 'number' and (v #>> '{}')::numeric between 1 and 9
    then round((v #>> '{}')::numeric * 2) / 2 end;
$$;

-- ── hooks ───────────────────────────────────────────────────────────────

create or replace function public.classroom_oratio_clean_settings(p jsonb)
returns jsonb language sql immutable as $$
  select jsonb_strip_nulls(jsonb_build_object('target_band', case when oratio_band(p->'target_band') >= 4 then oratio_band(p->'target_band') end));
$$;

create or replace function public.classroom_oratio_clean_payload(p_kind text, p jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  ids jsonb;
  s int;
  m int;
begin
  if p_kind = 'topic' then
    if char_length(trim(coalesce(p->>'category', ''))) not between 2 and 80 then raise exception 'bad payload'; end if;
    return jsonb_build_object(
      'category', trim(p->>'category'),
      'part', case when p->>'part' in ('1','2','3') then (p->>'part')::int end,
      'sessions', least(greatest(coalesce((p->>'sessions')::int, 2), 1), 20));
  elsif p_kind = 'questions' then
    -- Only questions that exist.
    select coalesce(jsonb_agg(q.id::text order by q.part, q.id), '[]') into ids
    from ielts_questions q
    where q.id::text in (select x from jsonb_array_elements_text(coalesce(p->'question_ids', '[]')) x limit 60);
    if jsonb_array_length(ids) = 0 then raise exception 'no questions'; end if;
    if jsonb_array_length(ids) > 30 then raise exception 'bad payload'; end if;
    return jsonb_build_object('question_ids', ids);
  elsif p_kind = 'goal' then
    s := least(greatest(coalesce((p->>'sessions')::int, 0), 0), 50);
    m := least(greatest(coalesce((p->>'minutes')::int, 0), 0), 1000);
    if s = 0 and m = 0 then raise exception 'bad payload'; end if;
    return jsonb_build_object('sessions', s, 'minutes', m);
  end if;
  raise exception 'bad payload';
end;
$$;

-- Numbers only; progress only for this class's own Oratio assignments.
create or replace function public.classroom_oratio_clean_metrics(p_class uuid, p jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  progress jsonb;
  band jsonb;
  n constant int := 100000;
begin
  select coalesce(jsonb_object_agg(k, jsonb_build_object(
      'sessions', least(greatest(coalesce((v->>'sessions')::int, 0), 0), n),
      'minutes', least(greatest(coalesce((v->>'minutes')::int, 0), 0), n),
      'asked', least(greatest(coalesce((v->>'asked')::int, 0), 0), 100))), '{}') into progress
  from jsonb_each(coalesce(p->'progress', '{}')) e(k, v)
  where jsonb_typeof(v) = 'object'
    and exists (select 1 from cortex_class_assignments a where a.class_id = p_class and a.app = 'oratio' and a.id::text = k);
  if jsonb_typeof(p->'band') = 'object' then
    band := jsonb_strip_nulls(jsonb_build_object(
      'fluency', oratio_band(p->'band'->'fluency'), 'vocabulary', oratio_band(p->'band'->'vocabulary'),
      'grammar', oratio_band(p->'band'->'grammar'), 'pronunciation', oratio_band(p->'band'->'pronunciation'),
      'overall', oratio_band(p->'band'->'overall')));
    if band = '{}'::jsonb then band := null; end if;
  end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'sessions', least(greatest(coalesce((p->>'sessions')::int, 0), 0), n),
    'minutes', least(greatest(coalesce((p->>'minutes')::int, 0), 0), n * 10),
    'ratings', least(greatest(coalesce((p->>'ratings')::int, 0), 0), n),
    'band', band,
    'current_band', oratio_band(p->'current_band'),
    'target_band', oratio_band(p->'target_band'),
    'progress', progress));
end;
$$;

-- Ranked by minutes spoken: effort, never the band partners gave.
create or replace function public.classroom_oratio_rank(p jsonb)
returns numeric language sql immutable as $$
  select coalesce((p->>'minutes')::numeric, 0);
$$;

do $$
declare f text;
begin
  foreach f in array array['oratio_band(jsonb)', 'classroom_oratio_clean_settings(jsonb)', 'classroom_oratio_clean_payload(text, jsonb)',
    'classroom_oratio_clean_metrics(uuid, jsonb)', 'classroom_oratio_rank(jsonb)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

notify pgrst, 'reload schema';

